import api from './client'

export const employeeService = {
	async getEmployees(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee_name',
				'first_name',
				'last_name',
				'status',
				'company',
				'department',
				'designation',
				'date_of_joining',
				'employment_type',
				'reports_to',
				'cell_number',
				'company_email',
				'personal_email',
				'image',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'creation desc',
		}
		const res = await api.get('/api/resource/Employee', params)
		return res.data || []
	},

	async getEmployee(name) {
		const res = await api.get(`/api/resource/Employee/${encodeURIComponent(name)}`)
		return res.data
	},

	async createEmployee(data) {
		const res = await api.post('/api/resource/Employee', data)
		return res.data
	},

	async updateEmployee(name, data) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.update_employee_profile', {
			employee: name,
			data,
		})
		return res.message || res.data
	},

	async updateEmployeeStatus(name, status = 'Active') {
		const res = await api.post('/api/method/hrms.api.shift_checkout.update_employee_status', {
			employee: name,
			status,
		})
		return res.message || res.data
	},

	async deleteEmployee(name) {
		return api.delete(`/api/resource/Employee/${encodeURIComponent(name)}`)
	},

	async onboardCandidate(formData) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.onboard_candidate_to_employee', {
			job_offer: formData.job_offer,
			employee_name: formData.employee_name,
			gender: formData.gender,
			date_of_birth: formData.date_of_birth,
			date_of_joining: formData.date_of_joining,
			company: formData.company || 'Faircode',
			department: formData.department,
			designation: formData.designation,
			personal_email: formData.personal_email,
			company_email: formData.company_email,
		})
		return res.message || res.data
	},

	async getDepartments() {
		const res = await api.get('/api/resource/Department', {
			fields: JSON.stringify(['name', 'department_name', 'company']),
			limit_page_length: 100,
		})
		return res.data || []
	},

	async createDepartment(data) {
		const res = await api.post('/api/resource/Department', data)
		return res.data
	},

	async getDesignations() {
		const res = await api.get('/api/resource/Designation', {
			fields: JSON.stringify(['name', 'designation_name']),
			limit_page_length: 100,
		})
		return res.data || []
	},

	async createDesignation(data) {
		const res = await api.post('/api/resource/Designation', data)
		return res.data
	},

	async getCompanies() {
		const res = await api.get('/api/resource/Company', {
			fields: JSON.stringify(['name', 'company_name', 'default_currency']),
			limit_page_length: 50,
		})
		return res.data || []
	},

	async getBranches() {
		try {
			const res = await api.get('/api/resource/Branch', {
				fields: JSON.stringify(['name', 'branch_name']),
				limit_page_length: 50,
			})
			return res.data || []
		} catch {
			return []
		}
	},

	async getEmploymentTypes() {
		try {
			const res = await api.get('/api/resource/Employment Type', {
				fields: JSON.stringify(['name', 'employment_type_name']),
				limit_page_length: 50,
			})
			return res.data || []
		} catch {
			return []
		}
	},
}

export default employeeService

