import api from './client'

export const jobOpeningService = {
	async getJobOpenings(filters = {}, limit = 50) {
		const params = {
			fields: JSON.stringify([
				'name',
				'job_title',
				'department',
				'designation',
				'location',
				'employment_type',
				'planned_vacancies',
				'vacancies',
				'description',
				'status',
				'posted_on',
				'closes_on',
				'company',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'posted_on desc, creation desc',
		}
		const res = await api.get('/api/resource/Job Opening', params)
		return res.data || []
	},

	async getJobOpening(name) {
		const res = await api.get(`/api/resource/Job Opening/${encodeURIComponent(name)}`)
		return res.data
	},

	async createJobOpening(data) {
		const res = await api.post('/api/resource/Job Opening', data)
		return res.data
	},

	async updateJobOpening(name, data) {
		const res = await api.put(`/api/resource/Job Opening/${encodeURIComponent(name)}`, data)
		return res.data
	},
}

export default jobOpeningService

