import React from 'react'

export default function StatusBadge({ status }) {
  if (!status) return null

  const getStyle = (s) => {
    const val = String(s).toLowerCase()
    if (['active', 'present', 'cleared', 'accepted', 'submitted', 'approved', 'open', 'hire', 'strong hire'].includes(val)) {
      return 'bg-emerald-50 text-emerald-700 border-emerald-200'
    }
    if (['pending', 'under review', 'draft', 'application received', 'screening', 'awaiting response'].includes(val)) {
      return 'bg-amber-50 text-amber-700 border-amber-200'
    }
    if (['rejected', 'absent', 'cancelled', 'inactive', 'failed', 'withheld'].includes(val)) {
      return 'bg-rose-50 text-rose-700 border-rose-200'
    }
    if (['shortlisted', 'round 1 passed', 'round 2 passed', 'interview round 1', 'interview round 2', 'final selection'].includes(val)) {
      return 'bg-indigo-50 text-indigo-700 border-indigo-200'
    }
    if (['on leave', 'half day', 'work from home'].includes(val)) {
      return 'bg-blue-50 text-blue-700 border-blue-200'
    }
    return 'bg-slate-50 text-slate-700 border-slate-200'
  }

  return (
    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getStyle(status)}`}>
      {status}
    </span>
  )
}
