import React, { useEffect, useState } from 'react'
import salaryService from '../../services/erpnext/salary'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus } from 'lucide-react'

export default function SalaryComponents() {
  const [components, setComponents] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    type: 'Earning',
    salary_component_abbr: '',
    description: '',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const data = await salaryService.getSalaryComponents()
      setComponents(data || [])
    } catch (err) {
      console.error('Failed to load salary components:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleCreateSubmit = async (e) => {
    e.preventDefault()
    try {
      await salaryService.createSalaryComponent({
        salary_component: formData.name,
        name: formData.name,
        type: formData.type,
        salary_component_abbr: formData.salary_component_abbr || formData.name.slice(0, 5).toUpperCase(),
        description: formData.description,
      })
      toast.success(`Salary Component "${formData.name}" created in ERPNext!`)
      setModalOpen(false)
      setFormData({ name: '', type: 'Earning', salary_component_abbr: '', description: '' })
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to create Salary Component')
    }
  }

  const columns = [
    { header: 'Component Name', accessor: 'name', className: 'font-semibold' },
    { header: 'Abbr', accessor: 'salary_component_abbr', className: 'font-mono text-xs' },
    {
      header: 'Type',
      render: row => (
        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
          row.type === 'Earning' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-rose-50 text-rose-700 border border-rose-200'
        }`}>
          {row.type}
        </span>
      ),
    },
    { header: 'Description', accessor: 'description' },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Salary Components</h1>
          <p className="text-xs text-slate-500 mt-1">Configured ERPNext Salary Components for earnings and statutory deductions</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5 transition-all"
        >
          <Plus className="w-4 h-4" /> Create Component
        </button>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 p-6 shadow-sm space-y-4">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Formula Definitions</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
          <div className="bg-emerald-50/50 p-4 rounded-xl border border-emerald-100 space-y-2">
            <div className="font-bold text-emerald-900">Earnings Formulas</div>
            <div><span className="font-semibold">Basic:</span> <code className="font-mono">base * 0.50</code></div>
            <div><span className="font-semibold">CA:</span> Fixed ₹2,000</div>
            <div><span className="font-semibold">HRA:</span> <code className="font-mono">base * 0.35</code></div>
            <div><span className="font-semibold">Other Allowance:</span> <code className="font-mono">(HRA + CA) / total_working_days * payment_days</code></div>
            <div><span className="font-semibold">Overtime:</span> <code className="font-mono">custom_overtime_hours * (base / total_working_days / 8) * 1.75</code></div>
          </div>
          <div className="bg-rose-50/50 p-4 rounded-xl border border-rose-100 space-y-2">
            <div className="font-bold text-rose-900">Statutory Deductions</div>
            <div><span className="font-semibold">PF:</span> <code className="font-mono">12% of Basic (B * 0.12)</code></div>
            <div><span className="font-semibold">ESI:</span> <code className="font-mono">0.75% of Gross (gross_pay * 0.0075)</code></div>
            <div><span className="font-semibold">Labour Welfare Fund:</span> Fixed ₹200</div>
          </div>
        </div>
      </div>

      <DataTable
        columns={columns}
        data={components}
        searchField="name"
        searchPlaceholder="Search components..."
        loading={loading}
      />

      {/* Create Salary Component Modal */}
      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Create Salary Component in ERPNext">
        <form onSubmit={handleCreateSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Component Name</label>
            <input
              type="text"
              required
              placeholder="e.g. Special Performance Bonus, Medical Allowance"
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Type</label>
              <select
                value={formData.type}
                onChange={e => setFormData({ ...formData, type: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
              >
                <option value="Earning">Earning</option>
                <option value="Deduction">Deduction</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Abbreviation (Optional)</label>
              <input
                type="text"
                placeholder="e.g. SPB"
                value={formData.salary_component_abbr}
                onChange={e => setFormData({ ...formData, salary_component_abbr: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none font-mono"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Description</label>
            <input
              type="text"
              placeholder="Optional description"
              value={formData.description}
              onChange={e => setFormData({ ...formData, description: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Create in ERPNext
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
