import api from './client'

function getLocalDatetimeString(date = new Date()) {
	const pad = (n) => String(n).padStart(2, '0')
	const year = date.getFullYear()
	const month = pad(date.getMonth() + 1)
	const day = pad(date.getDate())
	const hours = pad(date.getHours())
	const minutes = pad(date.getMinutes())
	const seconds = pad(date.getSeconds())
	return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`
}

export const attendanceService = {
	async getAttendance(filters = {}, limit = 100) {
		const effectiveFilters = { docstatus: ['!=', 2], ...filters }
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'attendance_date',
				'status',
				'working_hours',
				'shift',
				'in_time',
				'out_time',
				'docstatus',
			]),
			filters: JSON.stringify(effectiveFilters),
			limit_page_length: limit,
			order_by: 'attendance_date desc, creation desc',
		}
		const res = await api.get('/api/resource/Attendance', params)
		return res.data || []
	},

	async getCheckins(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'log_type',
				'time',
				'shift',
				'device_id',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'time desc',
		}
		const res = await api.get('/api/resource/Employee Checkin', params)
		return res.data || []
	},

	async checkIn(employee, time = null) {
		const checkinTime = time || getLocalDatetimeString()
		const res = await api.post('/api/method/hrms.api.shift_checkout.record_employee_checkin', {
			employee,
			time: checkinTime,
			device_id: 'Employee Web Terminal',
		})
		return res.message || res.data
	},

	async checkOut(employee, time = null) {
		const checkoutTime = time || getLocalDatetimeString()
		const res = await api.post('/api/method/hrms.api.shift_checkout.record_employee_checkout', {
			employee,
			time: checkoutTime,
			device_id: 'Employee Web Terminal',
		})
		return res.message || res.data
	},

	async markAttendance({ employee, attendance_date, status = 'Present', working_hours = 8.0, shift = null }) {
		const res = await api.post('/api/resource/Attendance', {
			employee,
			attendance_date,
			status,
			working_hours,
			shift,
			docstatus: 1, // Submit attendance directly to ERPNext
		})
		return res.data
	},

	async processAutoCheckoutAndAttendance(employee = null, forceCheckout = false) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.process_auto_checkout_and_attendance', {
			employee,
			force_checkout: forceCheckout ? 1 : 0,
		})
		return res.message
	},
}

export default attendanceService

