import React, { useEffect, useState } from 'react'
import salaryService from '../../services/erpnext/salary'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus, Edit2 } from 'lucide-react'

export default function SalaryStructures() {
  const [structures, setStructures] = useState([])
  const [loading, setLoading] = useState(true)
  const [createModalOpen, setCreateModalOpen] = useState(false)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [editFormData, setEditFormData] = useState(null)
  const [formData, setFormData] = useState({
    name: '',
    company: 'Faircode',
    currency: 'INR',
    payroll_frequency: 'Monthly',
    is_active: 'Yes',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const data = await salaryService.getSalaryStructures()
      setStructures(data || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleCreateSubmit = async (e) => {
    e.preventDefault()
    try {
      // Create Salary Structure with standard earnings and deductions formulas
      const payload = {
        name: formData.name,
        company: formData.company,
        currency: formData.currency,
        payroll_frequency: formData.payroll_frequency,
        is_active: formData.is_active,
        docstatus: 1, // submitted
        earnings: [
          { salary_component: 'Basic', formula: 'base * 0.50', amount_based_on_formula: 1, depends_on_payment_days: 1 },
          { salary_component: 'CA', amount: 2000, amount_based_on_formula: 0, depends_on_payment_days: 1 },
          { salary_component: 'House Rent Allowance', formula: 'base * 0.35', amount_based_on_formula: 1, depends_on_payment_days: 1 },
          { salary_component: 'Other Allowance', formula: '(HRA + CA) / total_working_days * payment_days', amount_based_on_formula: 1, depends_on_payment_days: 1 },
          { salary_component: 'Overtime', formula: 'custom_overtime_hours * (base / total_working_days / 8) * 1.75', amount_based_on_formula: 1, depends_on_payment_days: 1 },
        ],
        deductions: [
          { salary_component: 'Provident Fund', formula: 'B * 0.12', amount_based_on_formula: 1 },
          { salary_component: 'ESI', formula: 'gross_pay * 0.0075', amount_based_on_formula: 1 },
          { salary_component: 'Labour Welfare Fund', amount: 200, amount_based_on_formula: 0 },
        ],
      }
      await salaryService.createSalaryStructure(payload)
      toast.success(`Salary Structure ${formData.name} created in ERPNext`)
      setCreateModalOpen(false)
      setFormData({
        name: '',
        company: 'Faircode',
        currency: 'INR',
        payroll_frequency: 'Monthly',
        is_active: 'Yes',
      })
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to create Salary Structure')
    }
  }

  const columns = [
    { header: 'Structure Name', accessor: 'name', className: 'font-semibold text-slate-800' },
    { header: 'Company', accessor: 'company' },
    { header: 'Currency', accessor: 'currency' },
    { header: 'Frequency', accessor: 'payroll_frequency' },
    { header: 'Active', render: row => <StatusBadge status={row.is_active || 'Yes'} /> },
    { header: 'Status', render: row => <StatusBadge status={row.docstatus === 1 ? 'Submitted' : 'Draft'} /> },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Salary Structures</h1>
          <p className="text-xs text-slate-500 mt-1">Configured monthly salary calculation structures</p>
        </div>
        <button
          onClick={() => setCreateModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Create Structure
        </button>
      </div>

      <DataTable
        columns={columns}
        data={structures}
        searchField="name"
        searchPlaceholder="Search salary structures..."
        loading={loading}
      />

      {/* Create Salary Structure Modal */}
      <Modal isOpen={createModalOpen} onClose={() => setCreateModalOpen(false)} title="Create New Salary Structure in ERPNext">
        <form onSubmit={handleCreateSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Structure Name</label>
            <input
              type="text"
              required
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              placeholder="e.g. Standard Executive Salary Structure"
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Company</label>
              <input
                type="text"
                readOnly
                value={formData.company}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 bg-slate-50 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Currency</label>
              <input
                type="text"
                readOnly
                value={formData.currency}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 bg-slate-50 outline-none"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Frequency</label>
              <select
                value={formData.payroll_frequency}
                onChange={e => setFormData({ ...formData, payroll_frequency: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
              >
                <option value="Monthly">Monthly</option>
                <option value="Biweekly">Biweekly</option>
                <option value="Weekly">Weekly</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Active</label>
              <select
                value={formData.is_active}
                onChange={e => setFormData({ ...formData, is_active: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
              >
                <option value="Yes">Yes</option>
                <option value="No">No</option>
              </select>
            </div>
          </div>
          <div className="bg-slate-50 p-3 rounded-lg border border-slate-100 text-[11px] text-slate-600 space-y-1">
            <div className="font-semibold text-slate-700">Configured Component Rules:</div>
            <div>• Earnings: Basic (50%), CA (₹2,000), HRA (35%), Other Allowance ((HRA+CA)/26*payment_days), Overtime (1.75x)</div>
            <div>• Deductions: PF (12% of Basic), ESI (0.75% of Gross), Labour Welfare Fund (₹200)</div>
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setCreateModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Create in ERPNext
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
