import api from './client'

export const leaveService = {
	async getLeaveTypes() {
		const res = await api.get('/api/resource/Leave Type', {
			fields: JSON.stringify(['name', 'leave_type_name', 'max_leaves_allowed', 'is_carry_forward', 'is_lwp']),
			limit_page_length: 50,
		})
		return res.data || []
	},

	async createLeaveType(data) {
		const res = await api.post('/api/resource/Leave Type', data)
		return res.data
	},

	async getLeaveAllocations(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'leave_type',
				'from_date',
				'to_date',
				'new_leaves_allocated',
				'total_leaves_allocated',
				'docstatus',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'from_date desc',
		}
		const res = await api.get('/api/resource/Leave Allocation', params)
		return res.data || []
	},

	async createLeaveAllocation(data) {
		const res = await api.post('/api/resource/Leave Allocation', {
			...data,
			docstatus: 1, // submitted directly
		})
		return res.data
	},

	async getLeaveApplications(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'leave_type',
				'from_date',
				'to_date',
				'total_leave_days',
				'description',
				'status',
				'posting_date',
				'docstatus',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'posting_date desc, creation desc',
		}
		const res = await api.get('/api/resource/Leave Application', params)
		return res.data || []
	},

	async createLeaveApplication(data) {
		const res = await api.post('/api/resource/Leave Application', {
			...data,
			leave_approver: data.leave_approver || 'Administrator',
			status: data.status || 'Open',
		})
		return res.data
	},

	async updateLeaveApplicationStatus(name, status) {
		const docstatus = status === 'Approved' ? 1 : (status === 'Rejected' ? 2 : 0)
		const res = await api.put(`/api/resource/Leave Application/${encodeURIComponent(name)}`, {
			status,
			docstatus,
		})
		return res.data
	},

	async approveLeaveApplication(name) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.approve_leave_application', {
			name,
		})
		return res.message || res.data
	},

	async rejectLeaveApplication(name) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.reject_leave_application', {
			name,
		})
		return res.message || res.data
	},

	async getLeaveBalances(employee) {
		if (!employee) return []
		try {
			const res = await api.get('/api/method/hrms.api.shift_checkout.get_employee_leave_balances', {
				employee,
			})
			if (res && res.message && Array.isArray(res.message)) {
				return res.message
			}
		} catch (err) {
			console.warn('Backend get_employee_leave_balances failed, falling back to DocType calculation:', err)
		}

		try {
			const allocations = await this.getLeaveAllocations({ employee, docstatus: 1 })
			const applications = await this.getLeaveApplications({ employee, status: 'Approved' }).catch(() => [])

			const balances = {}
			for (const alloc of allocations) {
				const lt = alloc.leave_type
				balances[lt] = (balances[lt] || 0) + (alloc.total_leaves_allocated || alloc.new_leaves_allocated || 0)
			}

			for (const app of applications) {
				const lt = app.leave_type
				balances[lt] = (balances[lt] || 0) - (app.total_leave_days || 0)
			}

			return Object.entries(balances).map(([leave_type, balance]) => ({
				leave_type,
				balance: Math.max(0, balance),
			}))
		} catch (fallbackErr) {
			console.error('Failed to compute leave balances:', fallbackErr)
			return []
		}
	},
}

export default leaveService

