import React, { useEffect, useState } from 'react'
import salaryService from '../../services/erpnext/salary'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus } from 'lucide-react'

export default function SalaryAssignments() {
  const [assignments, setAssignments] = useState([])
  const [employees, setEmployees] = useState([])
  const [structures, setStructures] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    employee: '',
    salary_structure: 'Standard Monthly Salary Structure',
    from_date: '2026-09-01',
    base: 40000,
    company: 'Faircode',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    const [aList, empList, sList] = await Promise.all([
      salaryService.getSalaryStructureAssignments(),
      employeeService.getEmployees(),
      salaryService.getSalaryStructures(),
    ])
    setAssignments(aList)
    setEmployees(empList)
    setStructures(sList)
    if (empList.length > 0 && !formData.employee) {
      setFormData(prev => ({ ...prev, employee: empList[0].name }))
    }
    setLoading(false)
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await salaryService.createSalaryStructureAssignment(formData)
      toast.success('Salary Structure assigned to employee in ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Assignment failed')
    }
  }

  const columns = [
    { header: 'ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Employee', accessor: 'employee_name', className: 'font-semibold' },
    { header: 'Salary Structure', accessor: 'salary_structure' },
    { header: 'From Date', accessor: 'from_date' },
    { header: 'Base Salary', render: row => <span className="font-bold text-slate-800">₹{parseFloat(row.base || 0).toLocaleString()}</span> },
    { header: 'Status', render: row => <StatusBadge status={row.docstatus === 1 ? 'Submitted' : 'Draft'} /> },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Salary Structure Assignments</h1>
          <p className="text-xs text-slate-500 mt-1">Assign salary structure and configured base monthly salary</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Assign Structure
        </button>
      </div>

      <DataTable
        columns={columns}
        data={assignments}
        searchField="employee_name"
        searchPlaceholder="Search assignments..."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Assign Salary Structure">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Employee</label>
            <select
              value={formData.employee}
              onChange={e => setFormData({ ...formData, employee: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {employees.map(emp => (
                <option key={emp.name} value={emp.name}>{emp.employee_name} ({emp.name})</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Salary Structure</label>
            <select
              value={formData.salary_structure}
              onChange={e => setFormData({ ...formData, salary_structure: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {structures.map(st => (
                <option key={st.name} value={st.name}>{st.name}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Base Monthly Salary (₹)</label>
              <input
                type="number"
                required
                value={formData.base}
                onChange={e => setFormData({ ...formData, base: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">From Date</label>
              <input
                type="date"
                required
                value={formData.from_date}
                onChange={e => setFormData({ ...formData, from_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Confirm Assignment
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
