import React, { useEffect, useState } from 'react'
import leaveService from '../../services/erpnext/leave'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus, Check, X } from 'lucide-react'

export default function LeaveApplications() {
  const [leaves, setLeaves] = useState([])
  const [employees, setEmployees] = useState([])
  const [leaveTypes, setLeaveTypes] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    employee: '',
    leave_type: 'Casual Leave',
    from_date: new Date().toISOString().split('T')[0],
    to_date: new Date().toISOString().split('T')[0],
    description: 'Personal leave',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [lList, empList, ltList] = await Promise.all([
        leaveService.getLeaveApplications(),
        employeeService.getEmployees(),
        leaveService.getLeaveTypes(),
      ])
      setLeaves(lList || [])
      setEmployees(empList || [])
      setLeaveTypes(ltList || [])
      if (empList && empList.length > 0 && !formData.employee) {
        setFormData(prev => ({ ...prev, employee: empList[0].name }))
      }
    } catch (err) {
      console.error('Failed to load leave applications:', err)
      toast.error('Failed to load leave applications from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await leaveService.createLeaveApplication(formData)
      toast.success('Leave Application submitted to ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to submit leave application')
    }
  }

  const handleApprove = async (name) => {
    try {
      await leaveService.approveLeaveApplication(name)
      toast.success('Leave approved in ERPNext')
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Approval failed')
    }
  }

  const handleReject = async (name) => {
    try {
      await leaveService.rejectLeaveApplication(name)
      toast.success('Leave rejected in ERPNext')
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Rejection failed')
    }
  }

  const columns = [
    { header: 'ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Employee', accessor: 'employee_name', className: 'font-semibold' },
    { header: 'Leave Type', accessor: 'leave_type' },
    { header: 'From Date', accessor: 'from_date' },
    { header: 'To Date', accessor: 'to_date' },
    { header: 'Total Days', accessor: 'total_leave_days' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: row => (
        row.status === 'Open' || row.status === 'Applied' ? (
          <div className="flex items-center gap-1.5">
            <button
              onClick={() => handleApprove(row.name)}
              className="px-2 py-1 text-xs font-semibold text-emerald-700 bg-emerald-50 border border-emerald-200 rounded hover:bg-emerald-100 flex items-center gap-1"
            >
              <Check className="w-3 h-3" /> Approve
            </button>
            <button
              onClick={() => handleReject(row.name)}
              className="px-2 py-1 text-xs font-semibold text-rose-700 bg-rose-50 border border-rose-200 rounded hover:bg-rose-100 flex items-center gap-1"
            >
              <X className="w-3 h-3" /> Reject
            </button>
          </div>
        ) : null
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Leave Applications</h1>
          <p className="text-xs text-slate-500 mt-1">ERPNext Leave Application workflow records</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Apply for Leave
        </button>
      </div>

      <DataTable
        columns={columns}
        data={leaves}
        searchField="employee_name"
        searchPlaceholder="Search leave applications..."
        emptyMessage="No leave applications found."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Apply for Leave">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Employee</label>
            <select
              value={formData.employee}
              onChange={e => setFormData({ ...formData, employee: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {employees.map(emp => (
                <option key={emp.name} value={emp.name}>{emp.employee_name} ({emp.name})</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Leave Type</label>
            <select
              value={formData.leave_type}
              onChange={e => setFormData({ ...formData, leave_type: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {leaveTypes.map(lt => (
                <option key={lt.name} value={lt.name}>{lt.name}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">From Date</label>
              <input
                type="date"
                required
                value={formData.from_date}
                onChange={e => setFormData({ ...formData, from_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">To Date</label>
              <input
                type="date"
                required
                value={formData.to_date}
                onChange={e => setFormData({ ...formData, to_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Reason</label>
            <textarea
              rows="3"
              value={formData.description}
              onChange={e => setFormData({ ...formData, description: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Submit Leave
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
