import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import dashboardService from '../../services/erpnext/dashboard'
import { Briefcase, Users, UserCheck, Calendar, FileCheck, ArrowRight, Plus } from 'lucide-react'

export default function RecruitmentDashboard() {
  const [pipeline, setPipeline] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    dashboardService.getMetrics()
      .then(data => {
        setPipeline(data.recruitmentPipeline || [])
      })
      .catch(err => {
        console.error('Failed to load recruitment metrics:', err)
      })
      .finally(() => {
        setLoading(false)
      })
  }, [])

  const steps = [
    { title: '1. Job Openings', desc: 'Create & manage active job openings', to: '/job-openings', icon: Briefcase, color: 'text-indigo-600 bg-indigo-50 border-indigo-200' },
    { title: '2. Job Applicants', desc: 'Candidate applications received', to: '/applicants', icon: Users, color: 'text-blue-600 bg-blue-50 border-blue-200' },
    { title: '3. Application Screening', desc: 'Review & shortlist qualified talent', to: '/screening', icon: UserCheck, color: 'text-amber-600 bg-amber-50 border-amber-200' },
    { title: '4. Multi-Round Interviews', desc: 'Technical, Managerial & HR evaluation', to: '/interviews', icon: Calendar, color: 'text-purple-600 bg-purple-50 border-purple-200' },
    { title: '5. Selection & Job Offer', desc: 'Issue formal offers to candidates', to: '/job-offers', icon: FileCheck, color: 'text-emerald-600 bg-emerald-50 border-emerald-200' },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Recruitment Lifecycle</h1>
          <p className="text-xs text-slate-500 mt-1">End-to-end recruitment process integrated with ERPNext</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {steps.map((step, idx) => {
          const Icon = step.icon
          return (
            <div key={idx} className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm hover:shadow transition-all flex flex-col justify-between">
              <div>
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center mb-3 border ${step.color}`}>
                  <Icon className="w-5 h-5" />
                </div>
                <h3 className="font-bold text-slate-800 text-base">{step.title}</h3>
                <p className="text-xs text-slate-500 mt-1">{step.desc}</p>
              </div>
              <div className="mt-5 pt-3 border-t border-slate-100 flex items-center justify-end">
                <Link
                  to={step.to}
                  className="text-xs font-semibold text-indigo-600 hover:text-indigo-700 flex items-center gap-1"
                >
                  Enter Module <ArrowRight className="w-3.5 h-3.5" />
                </Link>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
