import React, { useEffect, useState } from 'react'
import jobOpeningService from '../../services/erpnext/jobOpenings'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus } from 'lucide-react'

export default function JobOpenings() {
  const [openings, setOpenings] = useState([])
  const [departments, setDepartments] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [editFormData, setEditFormData] = useState(null)
  const [formData, setFormData] = useState({
    job_title: '',
    designation: 'Software Developer',
    department: 'Information Technology - F',
    planned_vacancies: 1,
    status: 'Open',
    description: '',
    company: 'Faircode',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [oList, dList] = await Promise.all([
        jobOpeningService.getJobOpenings(),
        employeeService.getDepartments().catch(() => []),
      ])
      setOpenings(oList)
      setDepartments(dList)
      if (dList.length > 0 && !formData.department) {
        setFormData(prev => ({ ...prev, department: dList[0].name }))
      }
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await jobOpeningService.createJobOpening(formData)
      toast.success('Job Opening created in ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to create Job Opening')
    }
  }

  const handleEditSubmit = async (e) => {
    e.preventDefault()
    if (!editFormData) return
    try {
      await jobOpeningService.updateJobOpening(editFormData.name, {
        job_title: editFormData.job_title,
        designation: editFormData.designation,
        department: editFormData.department,
        planned_vacancies: editFormData.planned_vacancies,
        status: editFormData.status,
        description: editFormData.description,
      })
      toast.success('Job Opening updated in ERPNext')
      setEditModalOpen(false)
      setEditFormData(null)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to update Job Opening')
    }
  }

  const columns = [
    { header: 'ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Job Title', accessor: 'job_title', className: 'font-semibold' },
    { header: 'Designation', accessor: 'designation' },
    { header: 'Department', accessor: 'department' },
    { header: 'Vacancies', accessor: 'planned_vacancies' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: row => (
        <button
          onClick={() => {
            setEditFormData({ ...row })
            setEditModalOpen(true)
          }}
          className="px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
        >
          Edit
        </button>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Job Openings</h1>
          <p className="text-xs text-slate-500 mt-1">ERPNext Job Opening records</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Create Opening
        </button>
      </div>

      <DataTable
        columns={columns}
        data={openings}
        searchField="job_title"
        searchPlaceholder="Search openings..."
        emptyMessage="No job openings found."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Create Job Opening">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Job Title</label>
            <input
              type="text"
              required
              value={formData.job_title}
              onChange={e => setFormData({ ...formData, job_title: e.target.value })}
              placeholder="e.g. Senior Full Stack Developer"
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Designation</label>
              <select
                value={formData.designation}
                onChange={e => setFormData({ ...formData, designation: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              >
                <option value="Software Developer">Software Developer</option>
                <option value="HR Executive">HR Executive</option>
                <option value="Accountant">Accountant</option>
                <option value="Operations Executive">Operations Executive</option>
                <option value="Manager">Manager</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Department</label>
              <select
                value={formData.department}
                onChange={e => setFormData({ ...formData, department: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none bg-white"
              >
                {departments.length > 0 ? (
                  departments.map(d => (
                    <option key={d.name} value={d.name}>{d.department_name || d.name}</option>
                  ))
                ) : (
                  <option value="Information Technology - F">Information Technology</option>
                )}
              </select>
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Number of Positions</label>
            <input
              type="number"
              min="1"
              required
              value={formData.planned_vacancies}
              onChange={e => setFormData({ ...formData, planned_vacancies: parseInt(e.target.value) })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Description</label>
            <textarea
              rows="3"
              value={formData.description}
              onChange={e => setFormData({ ...formData, description: e.target.value })}
              placeholder="Key responsibilities and qualifications..."
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            />
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Save Job Opening
            </button>
          </div>
        </form>
      </Modal>

      {/* Edit Job Opening Modal */}
      <Modal isOpen={editModalOpen} onClose={() => setEditModalOpen(false)} title={`Edit Job Opening: ${editFormData?.name}`}>
        {editFormData && (
          <form onSubmit={handleEditSubmit} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Job Title</label>
              <input
                type="text"
                required
                value={editFormData.job_title || ''}
                onChange={e => setEditFormData({ ...editFormData, job_title: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Designation</label>
                <input
                  type="text"
                  required
                  value={editFormData.designation || ''}
                  onChange={e => setEditFormData({ ...editFormData, designation: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Department</label>
                <select
                  value={editFormData.department || ''}
                  onChange={e => setEditFormData({ ...editFormData, department: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
                >
                  {departments.map(d => (
                    <option key={d.name} value={d.name}>{d.department_name || d.name}</option>
                  ))}
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Vacancies</label>
                <input
                  type="number"
                  min="1"
                  required
                  value={editFormData.planned_vacancies || 1}
                  onChange={e => setEditFormData({ ...editFormData, planned_vacancies: parseInt(e.target.value) })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Status</label>
                <select
                  value={editFormData.status || 'Open'}
                  onChange={e => setEditFormData({ ...editFormData, status: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
                >
                  <option value="Open">Open</option>
                  <option value="Closed">Closed</option>
                  <option value="On Hold">On Hold</option>
                </select>
              </div>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Description</label>
              <textarea
                rows="3"
                value={editFormData.description || ''}
                onChange={e => setEditFormData({ ...editFormData, description: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
              <button
                type="button"
                onClick={() => setEditModalOpen(false)}
                className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
              >
                Update Opening
              </button>
            </div>
          </form>
        )}
      </Modal>
    </div>
  )
}
