import api from './client'

export const interviewService = {
	async getInterviews(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'interview_type',
				'job_applicant',
				'job_opening',
				'designation',
				'status',
				'scheduled_on',
				'from_time',
				'to_time',
				'average_rating',
				'interview_summary',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'scheduled_on desc, from_time desc',
		}
		const res = await api.get('/api/resource/Interview', params)
		return res.data || []
	},

	async getInterview(name) {
		const res = await api.get(`/api/resource/Interview/${encodeURIComponent(name)}`)
		return res.data
	},

	async scheduleInterview({
		job_applicant,
		applicant,
		interview_type, // "Round 1" or "Round 2"
		job_opening,
		designation,
		scheduled_on,
		from_time = '10:00:00',
		to_time = '11:00:00',
		interviewers = [],
		notes = '',
	}) {
		const targetApplicant = job_applicant || applicant
		// Ensure interview_type exists or create it
		if (interview_type) {
			try {
				await api.get(`/api/resource/Interview Type/${encodeURIComponent(interview_type)}`)
			} catch {
				await api.post('/api/resource/Interview Type', {
					interview_type_name: interview_type,
				})
			}
		}

		try {
			const res = await api.post('/api/method/hrms.api.shift_checkout.schedule_interview', {
				applicant: targetApplicant,
				interview_type,
				scheduled_on,
				from_time,
				to_time,
				interviewer: interviewers.length > 0 ? interviewers[0] : null,
			})
			return res.message || res.data
		} catch {
			const data = {
				job_applicant,
				interview_type,
				job_opening,
				designation,
				scheduled_on,
				from_time,
				to_time,
				status: 'Pending',
				interview_summary: notes,
				interview_details: interviewers.map((intvw) => ({ interviewer: intvw })),
			}
			const res = await api.post('/api/resource/Interview', data)
			return res.data
		}
	},

	async submitEvaluation({
		interview_name,
		technical_score = 8,
		communication_score = 8,
		overall_score = 8,
		feedback = '',
		recommendation = 'Hire',
	}) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.submit_interview_evaluation', {
			interview_name,
			technical_score,
			communication_score,
			overall_score,
			feedback,
			recommendation,
		})
		return res.message || res.data
	},

	async updateInterviewResult(name, { status, interview_summary, average_rating }) {
		const data = {
			status, // "Cleared", "Rejected", "Pending"
			interview_summary,
			average_rating,
		}
		const res = await api.put(`/api/resource/Interview/${encodeURIComponent(name)}`, data)
		return res.data
	},

	async getInterviewers() {
		// Get Users or Employees
		try {
			const res = await api.get('/api/resource/User', {
				fields: JSON.stringify(['name', 'full_name', 'email']),
				filters: JSON.stringify({ enabled: 1 }),
				limit_page_length: 50,
			})
			return res.data || []
		} catch {
			return []
		}
	},
}

export default interviewService

