import api from './client'

export const salaryService = {
	async getSalaryComponents() {
		const res = await api.get('/api/resource/Salary Component', {
			fields: JSON.stringify(['name', 'type', 'salary_component_abbr', 'description']),
			limit_page_length: 50,
		})
		return res.data || []
	},

	async createSalaryComponent(data) {
		const res = await api.post('/api/resource/Salary Component', data)
		return res.data
	},

	async getSalaryStructures(filters = {}, limit = 50) {
		const params = {
			fields: JSON.stringify(['name', 'company', 'is_active', 'payroll_frequency', 'currency']),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
		}
		const res = await api.get('/api/resource/Salary Structure', params)
		return res.data || []
	},

	async getSalaryStructure(name) {
		const res = await api.get(`/api/resource/Salary Structure/${encodeURIComponent(name)}`)
		return res.data
	},

	async createSalaryStructure(data) {
		const res = await api.post('/api/resource/Salary Structure', data)
		return res.data
	},

	async getSalaryStructureAssignments(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'salary_structure',
				'from_date',
				'base',
				'company',
				'currency',
				'docstatus',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'from_date desc',
		}
		const res = await api.get('/api/resource/Salary Structure Assignment', params)
		return res.data || []
	},

	async getSalaryAssignments(filters = {}, limit = 100) {
		return this.getSalaryStructureAssignments(filters, limit)
	},

	async createSalaryStructureAssignment({ employee, salary_structure, from_date, base, company = 'Faircode', currency = 'INR' }) {
		const res = await api.post('/api/resource/Salary Structure Assignment', {
			employee,
			salary_structure,
			from_date,
			base,
			company,
			currency,
			docstatus: 1, // Submit assignment
		})
		return res.data
	},
}

export default salaryService

