import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import payrollService from '../../services/erpnext/payroll'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Eye, Plus, FileText, PlayCircle, CheckCircle2, Send } from 'lucide-react'

export default function SalarySlips() {
  const [slips, setSlips] = useState([])
  const [employees, setEmployees] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [submittingBatch, setSubmittingBatch] = useState(false)
  const [submittingId, setSubmittingId] = useState(null)
  const [formData, setFormData] = useState({
    employee: '',
    start_date: '2026-09-01',
    end_date: '2026-09-30',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [slipData, empData] = await Promise.all([
        payrollService.getSalarySlips(),
        employeeService.getEmployees().catch(() => []),
      ])
      setSlips(slipData || [])
      setEmployees(empData || [])
      if (empData && empData.length > 0 && !formData.employee) {
        setFormData(prev => ({ ...prev, employee: empData[0].name }))
      }
    } catch (err) {
      console.error('Failed to load salary slips:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleBatchSubmitDrafts = async () => {
    setSubmittingBatch(true)
    try {
      const res = await payrollService.submitAllDraftSalarySlips('Faircode')
      toast.success(res.message || 'All draft salary slips submitted successfully!')
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to submit draft salary slips.')
    } finally {
      setSubmittingBatch(false)
    }
  }

  const handleSubmitSingleSlip = async (name) => {
    setSubmittingId(name)
    try {
      await payrollService.submitSalarySlip(name)
      toast.success(`Salary Slip ${name} submitted successfully in ERPNext!`)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || `Failed to submit Salary Slip ${name}`)
    } finally {
      setSubmittingId(null)
    }
  }

  const handleGenerateSlip = async (e) => {
    e.preventDefault()
    try {
      setSubmitting(true)
      const res = await payrollService.generatePayrollAndSlips({
        employee: formData.employee,
        start_date: formData.start_date,
        end_date: formData.end_date,
        company: 'Faircode',
      })
      toast.success(`Salary Slip generated for ${formData.employee}!`)
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to generate Salary Slip')
    } finally {
      setSubmitting(false)
    }
  }

  const draftCount = slips.filter(s => s.docstatus === 0 || s.status === 'Draft').length

  const columns = [
    { header: 'Salary Slip ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600 font-semibold' },
    { header: 'Employee', accessor: 'employee_name', className: 'font-semibold' },
    { header: 'Period', render: row => `${row.start_date} to ${row.end_date}` },
    { header: 'Gross Pay', render: row => <span className="font-semibold text-slate-800">₹{parseFloat(row.gross_pay || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span> },
    { header: 'Total Deductions', render: row => <span className="font-semibold text-rose-600">₹{parseFloat(row.total_deduction || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span> },
    { header: 'Net Pay', render: row => <span className="font-bold text-emerald-600">₹{parseFloat(row.net_pay || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span> },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: row => (
        <div className="flex items-center gap-1.5">
          {(row.docstatus === 0 || row.status === 'Draft') && (
            <button
              type="button"
              onClick={() => handleSubmitSingleSlip(row.name)}
              disabled={submittingId === row.name}
              className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-semibold text-emerald-700 bg-emerald-50 border border-emerald-300 rounded-lg hover:bg-emerald-100 disabled:opacity-50 transition-colors"
            >
              <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
              {submittingId === row.name ? 'Submitting...' : 'Submit'}
            </button>
          )}
          <Link
            to={`/salary-slips/${encodeURIComponent(row.name)}`}
            className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
          >
            <Eye className="w-3.5 h-3.5" /> View Slip
          </Link>
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Salary Slips</h1>
          <p className="text-xs text-slate-500 mt-1">Itemized salary slips with ERPNext formula calculations</p>
        </div>
        <div className="flex items-center gap-2.5">
          {draftCount > 0 && (
            <button
              onClick={handleBatchSubmitDrafts}
              disabled={submittingBatch}
              className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5 transition-all disabled:opacity-50"
            >
              <CheckCircle2 className="w-4 h-4" />
              <span>{submittingBatch ? 'Submitting...' : `Submit All Draft Slips (${draftCount})`}</span>
            </button>
          )}
          <button
            onClick={() => setModalOpen(true)}
            className="px-3.5 py-2 rounded-lg bg-emerald-600 text-white text-xs font-semibold hover:bg-emerald-700 shadow-sm flex items-center gap-1.5 transition-all"
          >
            <Plus className="w-4 h-4" /> Create Salary Slip
          </button>
        </div>
      </div>

      <DataTable
        columns={columns}
        data={slips}
        searchField="employee_name"
        searchPlaceholder="Search salary slips..."
        loading={loading}
      />

      {/* Generate Salary Slip Modal */}
      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Generate Employee Salary Slip in ERPNext">
        <form onSubmit={handleGenerateSlip} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Employee</label>
            <select
              required
              value={formData.employee}
              onChange={e => setFormData({ ...formData, employee: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
            >
              {employees.map(emp => (
                <option key={emp.name} value={emp.name}>{emp.employee_name} ({emp.name})</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Start Date</label>
              <input
                type="date"
                required
                value={formData.start_date}
                onChange={e => setFormData({ ...formData, start_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">End Date</label>
              <input
                type="date"
                required
                value={formData.end_date}
                onChange={e => setFormData({ ...formData, end_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="p-3 bg-emerald-50 rounded-lg border border-emerald-100 text-xs text-emerald-900">
            This will calculate statutory earnings, overtime hours, and PF/ESI deductions for the period and generate the verified Salary Slip in ERPNext.
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="px-4 py-2 text-xs font-semibold text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg shadow-sm flex items-center gap-1.5"
            >
              {submitting ? 'Calculating in ERPNext...' : 'Generate Slip'}
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
