import React, { useState, useEffect } from 'react'
import { Outlet } from 'react-router-dom'
import CandidateSidebar from './CandidateSidebar'
import CandidateNavbar from './CandidateNavbar'

export default function CandidateLayout() {
  const [sidebarOpen, setSidebarOpen] = useState(false)

  useEffect(() => {
    document.documentElement.classList.add('portal-candidate')
    return () => {
      document.documentElement.classList.remove('portal-candidate')
    }
  }, [])

  return (
    <div className="min-h-screen bg-slate-50 flex portal-candidate">
      <CandidateSidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <div className="flex-1 flex flex-col lg:pl-64 min-w-0">
        <CandidateNavbar onMenuClick={() => setSidebarOpen(true)} />
        <main className="flex-1 p-4 sm:p-8 max-w-7xl w-full mx-auto">
          <Outlet />
        </main>
      </div>
    </div>
  )
}

