import React, { useState, useEffect } from 'react'
import { Outlet } from 'react-router-dom'
import UserSidebar from './UserSidebar'
import UserNavbar from './UserNavbar'

export default function UserLayout() {
  const [sidebarOpen, setSidebarOpen] = useState(false)

  useEffect(() => {
    document.documentElement.classList.add('portal-employee')
    return () => {
      document.documentElement.classList.remove('portal-employee')
    }
  }, [])

  return (
    <div className="min-h-screen bg-slate-50 flex portal-employee">
      <UserSidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <div className="flex-1 flex flex-col lg:pl-64 min-w-0">
        <UserNavbar onMenuClick={() => setSidebarOpen(true)} />
        <main className="flex-1 p-4 sm:p-8 max-w-7xl w-full mx-auto">
          <Outlet />
        </main>
      </div>
    </div>
  )
}

