import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import {
  Clock,
  Calendar,
  DollarSign,
  CheckSquare,
  ShieldCheck,
  ArrowRight,
  RefreshCw,
  LogIn,
  LogOut,
  AlertCircle,
  Briefcase,
  Layers,
} from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import attendanceService from '../../services/erpnext/attendance'
import leaveService from '../../services/erpnext/leave'
import payrollService from '../../services/erpnext/payroll'
import shiftService from '../../services/erpnext/shifts'
import StatusBadge from '../../components/common/StatusBadge'
import StatCard from '../../components/common/StatCard'
import { useToast } from '../../components/common/Toast'

export default function UserDashboard() {
  const { user, employee } = useAuth()
  const empId = employee?.name || ''
  const toast = useToast()

  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [shiftStatus, setShiftStatus] = useState(null)
  const [recentLogs, setRecentLogs] = useState([])
  const [attendanceRecords, setAttendanceRecords] = useState([])
  const [leaveBalances, setLeaveBalances] = useState([])
  const [latestSlip, setLatestSlip] = useState(null)

  const loadData = async () => {
    if (!empId) {
      setLoading(false)
      return
    }
    setLoading(true)
    try {
      const [status, logs, attList, balances, slips] = await Promise.all([
        shiftService.getEmployeeShiftStatus(empId).catch(() => null),
        attendanceService.getCheckins({ employee: empId }, 5).catch(() => []),
        attendanceService.getAttendance({ employee: empId }, 5).catch(() => []),
        leaveService.getLeaveBalances(empId).catch(() => []),
        payrollService.getSalarySlips({ employee: empId }, 1).catch(() => []),
      ])
      setShiftStatus(status)
      setRecentLogs(logs || [])
      setAttendanceRecords(attList || [])
      setLeaveBalances(balances || [])
      setLatestSlip(slips && slips.length > 0 ? slips[0] : null)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [empId])

  const handleCheckIn = async () => {
    try {
      setActionLoading(true)
      await attendanceService.checkIn(empId)
      toast.success(`Check-In recorded for ${employee?.employee_name || empId}`)
      await loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Check-in failed')
    } finally {
      setActionLoading(false)
    }
  }

  const handleCheckOut = async () => {
    try {
      setActionLoading(true)
      await attendanceService.checkOut(empId)
      toast.success(`Check-Out recorded for ${employee?.employee_name || empId}`)
      await loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Check-out failed')
    } finally {
      setActionLoading(false)
    }
  }

  const handleAutoCheckout = async () => {
    try {
      setActionLoading(true)
      await attendanceService.processAutoCheckoutAndAttendance(empId, true)
      toast.success('Automatic 36H Checkout and attendance synced!')
      await loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Auto-checkout sync failed')
    } finally {
      setActionLoading(false)
    }
  }

  // Calculate Casual Leave remaining
  const casualLeaveObj = leaveBalances.find(b => b.leave_type.includes('Casual'))
  const casualLeave = casualLeaveObj ? casualLeaveObj.balance : (leaveBalances.length > 0 ? leaveBalances[0].balance : 0)

  // Dynamic non-contradictory Attendance Status calculation
  let displayAttendanceStatus = 'Not Marked'
  let displayAttendanceSubtitle = 'No active shift'
  let attendanceColor = 'slate'

  if (shiftStatus?.is_checked_in) {
    displayAttendanceStatus = 'Checked In'
    displayAttendanceSubtitle = '36H Shift in Progress'
    attendanceColor = 'emerald'
  } else if (attendanceRecords.length > 0) {
    const latestAtt = attendanceRecords[0]
    if (latestAtt.status === 'On Leave') {
      displayAttendanceStatus = 'On Leave'
      displayAttendanceSubtitle = latestAtt.leave_type ? `${latestAtt.leave_type}` : 'Approved Leave'
      attendanceColor = 'amber'
    } else if (latestAtt.status === 'Present') {
      displayAttendanceStatus = 'Present'
      const hrs = parseFloat(latestAtt.working_hours) || 0
      displayAttendanceSubtitle = hrs > 0 ? `${hrs.toFixed(1)} hrs logged` : 'Shift Completed'
      attendanceColor = 'emerald'
    } else {
      displayAttendanceStatus = latestAtt.status
      displayAttendanceSubtitle = latestAtt.attendance_date || 'Logged'
      attendanceColor = 'indigo'
    }
  }

  return (
    <div className="space-y-6">
      {/* Welcome Banner */}
      <div className="bg-gradient-to-r from-indigo-900 via-indigo-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white shadow-lg relative overflow-hidden">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/20 text-indigo-200 text-xs font-semibold mb-3 border border-indigo-400/20">
              <ShieldCheck className="w-3.5 h-3.5 text-emerald-400" />
              <span>ERPNext Production System • Employee Portal</span>
            </div>
            <h1 className="text-2xl sm:text-3xl font-bold tracking-tight">
              Welcome back, {employee?.first_name || user?.first_name || user?.full_name || 'Employee'}!
            </h1>
            <p className="text-indigo-200 text-xs sm:text-sm mt-1 max-w-xl">
              {employee?.designation || 'Staff'} {employee?.department ? `• ${employee.department}` : ''} {empId ? `• ID: ${empId}` : ''}
            </p>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={loadData}
              disabled={loading || actionLoading}
              className="px-3.5 py-2 rounded-xl bg-white/10 hover:bg-white/20 text-white text-xs font-semibold backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
              <span>Refresh Data</span>
            </button>
            <Link
              to="/user/profile"
              className="px-3.5 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold transition-colors flex items-center gap-1.5 shadow-md shadow-indigo-600/30"
            >
              <span>View Profile</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </div>
        </div>
      </div>

      {/* Overview Stat Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          title="Assigned Shift"
          value={shiftStatus?.shift || 'No Shift Assigned'}
          subtitle={shiftStatus?.duration_hours ? `Configured: ${shiftStatus.duration_hours} Hours` : (shiftStatus?.shift ? 'Standard Shift' : 'No Shift Schedule')}
          icon={Clock}
          color="indigo"
        />
        <StatCard
          title="Attendance Status"
          value={displayAttendanceStatus}
          subtitle={displayAttendanceSubtitle}
          icon={CheckSquare}
          color={attendanceColor}
        />
        <StatCard
          title="Casual Leave Balance"
          value={`${casualLeave} Days`}
          subtitle="Available for consumption"
          icon={Calendar}
          color="amber"
        />
        <StatCard
          title="Latest Net Pay"
          value={latestSlip?.net_pay != null ? `₹${Number(latestSlip.net_pay).toLocaleString('en-IN', { minimumFractionDigits: 2 })}` : 'N/A'}
          subtitle={latestSlip?.posting_date ? `Payslip ${latestSlip.posting_date}` : (latestSlip ? 'Current Payslip' : 'No Payslip Generated')}
          icon={DollarSign}
          color="purple"
        />
      </div>

      {/* Main Grid: Quick Check-In Terminal & Recent Activity */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Check-In / Check-Out Widget */}
        <div className="lg:col-span-1 bg-white rounded-2xl border border-slate-200 p-6 shadow-sm flex flex-col justify-between">
          <div>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
                <Clock className="w-4 h-4 text-indigo-600" />
                <span>Attendance Terminal</span>
              </h2>
              <span className={`text-[11px] font-semibold px-2 py-0.5 rounded-full ${shiftStatus?.is_checked_in ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-slate-50 text-slate-600 border border-slate-200'}`}>
                {shiftStatus?.is_checked_in ? '● Checked In' : '● Ready to Check In'}
              </span>
            </div>

            <div className="p-4 rounded-xl bg-slate-50 border border-slate-100 mb-5 space-y-2">
              <div className="flex items-center justify-between text-xs">
                <span className="text-slate-500">Employee:</span>
                <span className="font-semibold text-slate-800">{employee?.employee_name || user?.full_name || 'Staff Member'}</span>
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-slate-500">Shift Type:</span>
                <span className="font-semibold text-indigo-600">{shiftStatus?.shift || 'Standard Shift'}</span>
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-slate-500">Configured Duration:</span>
                <span className="font-medium text-slate-600">{shiftStatus?.duration_hours ? `${shiftStatus.duration_hours} Hours` : '-'}</span>
              </div>
              {shiftStatus?.last_in_time && shiftStatus?.is_checked_in && (
                <div className="flex items-center justify-between text-xs pt-1 border-t border-slate-200">
                  <span className="text-slate-500">Checked In At:</span>
                  <span className="font-mono text-indigo-600 font-semibold">{shiftStatus.last_in_time}</span>
                </div>
              )}
              {shiftStatus?.expected_checkout && (
                <div className="flex items-center justify-between text-xs pt-1 border-t border-slate-200">
                  <span className="text-slate-500">Expected Checkout:</span>
                  <span className="font-mono text-emerald-600 font-semibold">{shiftStatus.expected_checkout}</span>
                </div>
              )}
            </div>
          </div>

          <div className="space-y-2.5">
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={handleCheckIn}
                disabled={actionLoading || shiftStatus?.is_checked_in}
                title={shiftStatus?.is_checked_in ? "Already checked in" : "Record Check-In"}
                className="py-2.5 px-3 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold transition-all flex items-center justify-center gap-1.5 shadow-sm disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <LogIn className="w-3.5 h-3.5" />
                <span>{shiftStatus?.is_checked_in ? 'Checked In' : 'Check In (IN)'}</span>
              </button>
              <button
                onClick={handleCheckOut}
                disabled={actionLoading || !shiftStatus?.is_checked_in}
                title={!shiftStatus?.is_checked_in ? "No active check-in session" : "Record Check-Out"}
                className="py-2.5 px-3 rounded-xl bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold transition-all flex items-center justify-center gap-1.5 shadow-sm disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <LogOut className="w-3.5 h-3.5" />
                <span>Check Out (OUT)</span>
              </button>
            </div>

            <button
              onClick={handleAutoCheckout}
              disabled={actionLoading}
              className="w-full py-2 px-3 rounded-xl bg-indigo-50 hover:bg-indigo-100 text-indigo-700 text-xs font-semibold transition-all flex items-center justify-center gap-1.5 border border-indigo-200 disabled:opacity-50"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${actionLoading ? 'animate-spin' : ''}`} />
              <span>Trigger 36H Auto-Checkout Engine</span>
            </button>

            <Link
              to="/user/checkin"
              className="block text-center text-xs text-indigo-600 hover:text-indigo-800 font-medium pt-1"
            >
              Open Full Check-In Terminal →
            </Link>
          </div>
        </div>

        {/* Recent Attendance Records */}
        <div className="lg:col-span-2 bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
              <Calendar className="w-4 h-4 text-indigo-600" />
              <span>Recent Attendance Records</span>
            </h2>
            <Link
              to="/user/attendance"
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-800 flex items-center gap-1"
            >
              <span>View All</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-100 text-slate-400 font-semibold uppercase tracking-wider">
                  <th className="pb-2.5">Date</th>
                  <th className="pb-2.5">Status</th>
                  <th className="pb-2.5">Working Hours</th>
                  <th className="pb-2.5">Shift</th>
                  <th className="pb-2.5">In Time</th>
                  <th className="pb-2.5">Out Time</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {attendanceRecords.length === 0 ? (
                  <tr>
                    <td colSpan="6" className="py-6 text-center text-slate-400">
                      No recent attendance records found.
                    </td>
                  </tr>
                ) : (
                  attendanceRecords.map((att, idx) => (
                    <tr key={idx} className="hover:bg-slate-50/60">
                      <td className="py-3 font-semibold text-slate-800">{att.attendance_date}</td>
                      <td className="py-3">
                        <StatusBadge status={att.status} />
                      </td>
                      <td className="py-3 font-mono font-medium text-slate-700">
                        {att.working_hours ? `${att.working_hours} hrs` : '-'}
                      </td>
                      <td className="py-3 text-slate-600">{att.shift || '-'}</td>
                      <td className="py-3 font-mono text-slate-500">{att.in_time ? att.in_time.split(' ')[1] || att.in_time : '-'}</td>
                      <td className="py-3 font-mono text-slate-500">{att.out_time ? att.out_time.split(' ')[1] || att.out_time : '-'}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Secondary Grid: Recent Payslip & Leave Overview */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Latest Salary Slip Breakdown */}
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
              <DollarSign className="w-4 h-4 text-purple-600" />
              <span>Latest Salary Slip{latestSlip?.start_date ? ` (${new Date(latestSlip.start_date).toLocaleString('default', { month: 'long', year: 'numeric' })})` : ''}</span>
            </h2>
            <Link
              to="/user/salary"
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-800 flex items-center gap-1"
            >
              <span>All Slips</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </div>

          {latestSlip ? (
            <div className="space-y-3">
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-purple-50/60 border border-purple-100">
                <div>
                  <div className="text-xs text-purple-700 font-medium">Net Salary Payable</div>
                  <div className="text-xl font-bold text-purple-900 mt-0.5">
                    ₹{Number(latestSlip.net_pay || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </div>
                </div>
                <StatusBadge status={latestSlip.status || 'Draft'} />
              </div>

              <div className="grid grid-cols-2 gap-3 text-xs">
                <div className="p-3 rounded-lg bg-slate-50 border border-slate-100">
                  <div className="text-slate-400 font-medium">Gross Pay</div>
                  <div className="text-sm font-semibold text-slate-800 mt-0.5">
                    ₹{Number(latestSlip.gross_pay || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </div>
                </div>
                <div className="p-3 rounded-lg bg-slate-50 border border-slate-100">
                  <div className="text-slate-400 font-medium">Total Deductions</div>
                  <div className="text-sm font-semibold text-rose-600 mt-0.5">
                    -₹{Number(latestSlip.total_deduction || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </div>
                </div>
              </div>

              <div className="pt-2">
                <Link
                  to="/user/salary"
                  className="w-full py-2 px-3 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold transition-all flex items-center justify-center gap-1.5"
                >
                  <span>View Full Payslip Breakdown</span>
                  <ArrowRight className="w-3.5 h-3.5" />
                </Link>
              </div>
            </div>
          ) : (
            <div className="py-8 text-center text-slate-400 text-xs">
              No salary slip available for this period.
            </div>
          )}
        </div>

        {/* Leave Summary & Quick Application */}
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
              <Calendar className="w-4 h-4 text-amber-600" />
              <span>Leave Entitlements</span>
            </h2>
            <Link
              to="/user/leave"
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-800 flex items-center gap-1"
            >
              <span>Manage Leave</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </div>

          <div className="space-y-3">
            <div className="p-4 rounded-xl bg-amber-50/60 border border-amber-100 flex items-center justify-between">
              <div>
                <div className="text-xs font-medium text-amber-800">Casual Leave</div>
                <div className="text-lg font-bold text-amber-950 mt-0.5">{casualLeave} Days Available</div>
                <div className="text-[11px] text-amber-700">Valid: Jan 01, 2026 - Dec 31, 2026</div>
              </div>
              <div className="text-right">
                <span className="inline-block px-2 py-1 rounded-lg bg-white/80 border border-amber-200 text-amber-800 font-semibold text-xs">
                  12.0 Allocated
                </span>
              </div>
            </div>

            <div className="pt-2">
              <Link
                to="/user/leave"
                className="w-full py-2.5 px-3 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-semibold transition-all flex items-center justify-center gap-1.5 shadow-sm"
              >
                <span>Apply for Leave</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

