import React, { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import applicantService from '../../services/erpnext/applicants'
import employeeService from '../../services/erpnext/employees'
import { useToast } from '../../components/common/Toast'
import { UserCheck, ShieldCheck } from 'lucide-react'

export default function EmployeeOnboarding() {
  const [offers, setOffers] = useState([])
  const [formData, setFormData] = useState({
    job_offer: '',
    employee_name: '',
    gender: 'Male',
    date_of_birth: '1995-05-15',
    date_of_joining: new Date().toISOString().split('T')[0],
    company: 'Faircode',
    department: 'Information Technology',
    designation: 'Software Developer',
    personal_email: '',
    company_email: '',
  })
  const [loading, setLoading] = useState(false)
  const toast = useToast()
  const navigate = useNavigate()

  useEffect(() => {
    applicantService.getJobOffers().then(offerList => {
      setOffers(offerList)
      if (offerList.length > 0) {
        const off = offerList[0]
        setFormData(prev => ({
          ...prev,
          job_offer: off.name,
          employee_name: off.applicant_name,
          designation: off.designation || 'Software Developer',
          department: off.department || 'Information Technology',
          personal_email: off.applicant_email || '',
          company_email: `${(off.applicant_name || 'employee').toLowerCase().split(' ')[0]}@faircode.com`,
        }))
      }
    })
  }, [])

  const handleOfferChange = (offerId) => {
    const off = offers.find(o => o.name === offerId)
    if (off) {
      setFormData(prev => ({
        ...prev,
        job_offer: off.name,
        employee_name: off.applicant_name,
        designation: off.designation || 'Software Developer',
        department: off.department || 'Information Technology',
        personal_email: off.applicant_email || '',
        company_email: `${(off.applicant_name || 'employee').toLowerCase().split(' ')[0]}@faircode.com`,
      }))
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      setLoading(true)
      const emp = await employeeService.onboardCandidate(formData)
      toast.success(`Employee ${emp.name} successfully created in ERPNext!`)
      navigate(`/employees/${encodeURIComponent(emp.name)}`)
    } catch (err) {
      toast.error(err.userMessage || 'Failed to onboard candidate')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="max-w-3xl space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Employee Onboarding</h1>
        <p className="text-xs text-slate-500 mt-1">Convert accepted candidate job offers into real ERPNext Employee master records</p>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 p-6 shadow-sm">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Select Accepted Job Offer</label>
            <select
              value={formData.job_offer}
              onChange={e => handleOfferChange(e.target.value)}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {offers.map(off => (
                <option key={off.name} value={off.name}>{off.applicant_name} — {off.name} ({off.designation})</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Full Employee Name</label>
              <input
                type="text"
                required
                value={formData.employee_name}
                onChange={e => setFormData({ ...formData, employee_name: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Gender</label>
              <select
                value={formData.gender}
                onChange={e => setFormData({ ...formData, gender: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              >
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Other">Other</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Date of Joining</label>
              <input
                type="date"
                required
                value={formData.date_of_joining}
                onChange={e => setFormData({ ...formData, date_of_joining: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Date of Birth</label>
              <input
                type="date"
                required
                value={formData.date_of_birth}
                onChange={e => setFormData({ ...formData, date_of_birth: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Designation</label>
              <select
                value={formData.designation}
                onChange={e => setFormData({ ...formData, designation: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              >
                <option value="Software Developer">Software Developer</option>
                <option value="HR Executive">HR Executive</option>
                <option value="Accountant">Accountant</option>
                <option value="Operations Executive">Operations Executive</option>
                <option value="Manager">Manager</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Department</label>
              <select
                value={formData.department}
                onChange={e => setFormData({ ...formData, department: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              >
                <option value="Information Technology">Information Technology</option>
                <option value="Human Resources">Human Resources</option>
                <option value="Finance">Finance</option>
                <option value="Operations">Operations</option>
                <option value="Administration">Administration</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Personal Email</label>
              <input
                type="email"
                required
                value={formData.personal_email}
                onChange={e => setFormData({ ...formData, personal_email: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Company Email</label>
              <input
                type="email"
                required
                value={formData.company_email}
                onChange={e => setFormData({ ...formData, company_email: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="pt-4 border-t border-slate-100 flex justify-end">
            <button
              type="submit"
              disabled={loading}
              className="px-6 py-2.5 rounded-lg bg-indigo-600 text-white font-semibold text-xs hover:bg-indigo-700 shadow-sm flex items-center gap-2"
            >
              <ShieldCheck className="w-4 h-4" />
              <span>{loading ? 'Creating Employee in ERPNext...' : 'Create Employee Record'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}
