import api from './client'

export const authService = {
	async login(username, password) {
		const res = await api.post('/api/method/login', {
			usr: username,
			pwd: password,
		})
		return res
	},

	async logout() {
		return api.post('/api/method/logout')
	},

	async getLoggedUser() {
		const res = await api.get('/api/method/frappe.auth.get_logged_user')
		return res.message
	},

	async getCurrentUserInfo() {
		try {
			const res = await api.get('/api/method/hrms.api.get_current_user_info')
			return res.message || res.data || null
		} catch {
			return null
		}
	},

	isLoggedIn() {
		const cookies = new URLSearchParams(document.cookie.split('; ').join('&'))
		const userId = cookies.get('user_id')
		return !!userId && userId !== 'Guest'
	},
}

export default authService

