import React from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'
import { useAuth } from './context/AuthContext'
import Layout from './components/layout/Layout'
import UserLayout from './components/layout/UserLayout'

// Pages
// Existing Admin Pages (completely preserved)
import Login from './pages/Login'
import Dashboard from './pages/Dashboard'
import RecruitmentDashboard from './pages/recruitment/RecruitmentDashboard'
import JobOpenings from './pages/recruitment/JobOpenings'
import Applicants from './pages/recruitment/Applicants'
import CandidateList from './pages/recruitment/CandidateList'
import Screening from './pages/recruitment/Screening'
import Interviews from './pages/recruitment/Interviews'
import JobOffers from './pages/recruitment/JobOffers'
import EmployeeList from './pages/employees/EmployeeList'
import EmployeeProfile from './pages/employees/EmployeeProfile'
import EmployeeOnboarding from './pages/employees/EmployeeOnboarding'
import LeaveApplications from './pages/leave/LeaveApplications'
import LeaveAllocations from './pages/leave/LeaveAllocations'
import ShiftTypes from './pages/shifts/ShiftTypes'
import ShiftAssignments from './pages/shifts/ShiftAssignments'
import CheckinCheckout from './pages/attendance/CheckinCheckout'
import AttendanceList from './pages/attendance/AttendanceList'
import OvertimeList from './pages/overtime/OvertimeList'
import SalaryComponents from './pages/payroll/SalaryComponents'
import SalaryStructures from './pages/payroll/SalaryStructures'
import SalaryAssignments from './pages/payroll/SalaryAssignments'
import PayrollEntries from './pages/payroll/PayrollEntries'
import SalarySlips from './pages/payroll/SalarySlips'
import SalarySlipDetail from './pages/payroll/SalarySlipDetail'
import Signup from './pages/Signup'

// Dedicated User Pages for Employees
import UserDashboard from './pages/user/UserDashboard'
import UserProfile from './pages/user/UserProfile'
import UserCheckin from './pages/user/UserCheckin'
import UserAttendance from './pages/user/UserAttendance'
import UserLeave from './pages/user/UserLeave'
import UserShift from './pages/user/UserShift'
import UserSalary from './pages/user/UserSalary'

// Dedicated Candidate Portal
import CandidateLayout from './components/layout/CandidateLayout'
import CandidateDashboard from './pages/candidate/CandidateDashboard'
import CandidateJobs from './pages/candidate/CandidateJobs'
import CandidateApply from './pages/candidate/CandidateApply'
import CandidateApplications from './pages/candidate/CandidateApplications'
import CandidateInterviews from './pages/candidate/CandidateInterviews'
import CandidateNotifications from './pages/candidate/CandidateNotifications'
import CandidateProfile from './pages/candidate/CandidateProfile'
import AdminCandidateApplications from './pages/recruitment/CandidateApplications'

/**
 * AdminRoute: Verifies user is authenticated AND has Administrator / HR Manager privileges.
 * If user is a candidate or employee, redirects to their respective dashboard.
 */
function AdminRoute({ children }) {
  const { user, loading, isAdmin, isCandidate } = useAuth()

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white">
        <div className="w-8 h-8 border-2 border-indigo-500 border-r-transparent rounded-full animate-spin mr-3" />
        <span>Authenticating with ERPNext...</span>
      </div>
    )
  }

  if (!user) {
    return <Navigate to="/login" replace />
  }

  if (!isAdmin) {
    if (isCandidate) {
      return <Navigate to="/candidate/dashboard" replace />
    }
    return <Navigate to="/user/dashboard" replace />
  }

  return children
}

/**
 * UserRoute: Verifies user is authenticated employee.
 * Candidates are strictly blocked and redirected to /candidate/dashboard.
 */
function UserRoute({ children }) {
  const { user, loading, isCandidate, isEmployee, isAdmin } = useAuth()

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white">
        <div className="w-8 h-8 border-2 border-indigo-500 border-r-transparent rounded-full animate-spin mr-3" />
        <span>Authenticating with ERPNext...</span>
      </div>
    )
  }

  if (!user) {
    return <Navigate to="/login" replace />
  }

  // Candidate must NEVER access user/employee dashboard
  if (isCandidate) {
    return <Navigate to="/candidate/dashboard" replace />
  }

  // Only employees or admins can access
  if (!isEmployee && !isAdmin) {
    return <Navigate to="/login" replace />
  }

  return children
}

/**
 * CandidateRoute: Verifies user is authenticated candidate or admin.
 * Normal employees are redirected to /user/dashboard.
 */
function CandidateRoute({ children }) {
  const { user, loading, isCandidate, isEmployee, isAdmin } = useAuth()

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white">
        <div className="w-8 h-8 border-2 border-sky-500 border-r-transparent rounded-full animate-spin mr-3" />
        <span>Authenticating with ERPNext...</span>
      </div>
    )
  }

  if (!user) {
    return <Navigate to="/login" replace />
  }

  // Allow converted candidates to view their onboarding message in candidate portal; pure employees go to /user/dashboard
  if (isEmployee && !isAdmin && !user.roles?.includes('Candidate') && !user.email?.includes('candidate') && !user.username?.includes('candidate')) {
    return <Navigate to="/user/dashboard" replace />
  }

  if (!isCandidate && !isEmployee && !isAdmin) {
    return <Navigate to="/login" replace />
  }

  return children
}

/**
 * RootRedirect: Directs logged-in users to their respective default hub.
 */
function RootRedirect() {
  const { user, loading, isAdmin, isCandidate, isEmployee } = useAuth()

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white">
        <div className="w-8 h-8 border-2 border-indigo-500 border-r-transparent rounded-full animate-spin mr-3" />
        <span>Authenticating with ERPNext...</span>
      </div>
    )
  }

  if (!user) {
    return <Navigate to="/login" replace />
  }

  if (isAdmin) return <Navigate to="/dashboard" replace />
  if (isEmployee) return <Navigate to="/user/dashboard" replace />
  if (isCandidate) return <Navigate to="/candidate/dashboard" replace />
  return <Navigate to="/user/dashboard" replace />
}

export default function App() {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route path="/signup" element={<Signup />} />

      {/* Root redirect */}
      <Route path="/" element={<RootRedirect />} />

      {/* User Dashboard Routes (Dedicated Employee Portal) */}
      <Route
        path="/user"
        element={
          <UserRoute>
            <UserLayout />
          </UserRoute>
        }
      >
        <Route index element={<Navigate to="/user/dashboard" replace />} />
        <Route path="dashboard" element={<UserDashboard />} />
        <Route path="profile" element={<UserProfile />} />
        <Route path="checkin" element={<UserCheckin />} />
        <Route path="attendance" element={<UserAttendance />} />
        <Route path="leave" element={<UserLeave />} />
        <Route path="shift" element={<UserShift />} />
        <Route path="salary" element={<UserSalary />} />
        <Route path="*" element={<Navigate to="/user/dashboard" replace />} />
      </Route>

      {/* Candidate Portal Routes (Dedicated Applicant Portal) */}
      <Route
        path="/candidate"
        element={
          <CandidateRoute>
            <CandidateLayout />
          </CandidateRoute>
        }
      >
        <Route index element={<Navigate to="/candidate/dashboard" replace />} />
        <Route path="dashboard" element={<CandidateDashboard />} />
        <Route path="jobs" element={<CandidateJobs />} />
        <Route path="apply/:jobId" element={<CandidateApply />} />
        <Route path="apply" element={<CandidateApply />} />
        <Route path="applications" element={<CandidateApplications />} />
        <Route path="interviews" element={<CandidateInterviews />} />
        <Route path="notifications" element={<CandidateNotifications />} />
        <Route path="profile" element={<CandidateProfile />} />
        <Route path="*" element={<Navigate to="/candidate/dashboard" replace />} />
      </Route>

      {/* Admin Dashboard Routes (Fully Preserved with strict RBAC protection) */}
      <Route
        element={
          <AdminRoute>
            <Layout />
          </AdminRoute>
        }
      >
        <Route index element={<Navigate to="/dashboard" replace />} />
        <Route path="dashboard" element={<Dashboard />} />
        <Route path="/dashboard" element={<Dashboard />} />

        {/* Recruitment */}
        <Route path="recruitment" element={<RecruitmentDashboard />} />
        <Route path="job-openings" element={<JobOpenings />} />
        <Route path="candidates" element={<CandidateList />} />
        <Route path="applicants" element={<Applicants />} />
        <Route path="screening" element={<Screening />} />
        <Route path="interviews" element={<Interviews />} />
        <Route path="job-offers" element={<JobOffers />} />
        <Route path="candidate-applications" element={<AdminCandidateApplications />} />
        <Route path="/recruitment" element={<RecruitmentDashboard />} />
        <Route path="/job-openings" element={<JobOpenings />} />
        <Route path="/candidates" element={<CandidateList />} />
        <Route path="/applicants" element={<Applicants />} />
        <Route path="/screening" element={<Screening />} />
        <Route path="/interviews" element={<Interviews />} />
        <Route path="/job-offers" element={<JobOffers />} />
        <Route path="/candidate-applications" element={<AdminCandidateApplications />} />

        {/* Employees */}
        <Route path="employees" element={<EmployeeList />} />
        <Route path="employees/:id" element={<EmployeeProfile />} />
        <Route path="onboarding" element={<EmployeeOnboarding />} />
        <Route path="/employees" element={<EmployeeList />} />
        <Route path="/employees/:id" element={<EmployeeProfile />} />
        <Route path="/onboarding" element={<EmployeeOnboarding />} />

        {/* Leave */}
        <Route path="leave" element={<Navigate to="/leave/applications" replace />} />
        <Route path="leave/applications" element={<LeaveApplications />} />
        <Route path="leave/allocations" element={<LeaveAllocations />} />
        <Route path="/leave" element={<Navigate to="/leave/applications" replace />} />
        <Route path="/leave/applications" element={<LeaveApplications />} />
        <Route path="/leave/allocations" element={<LeaveAllocations />} />

        {/* Shifts */}
        <Route path="shifts" element={<ShiftTypes />} />
        <Route path="shift-assignments" element={<ShiftAssignments />} />
        <Route path="/shifts" element={<ShiftTypes />} />
        <Route path="/shift-assignments" element={<ShiftAssignments />} />

        {/* Attendance */}
        <Route path="attendance" element={<AttendanceList />} />
        <Route path="attendance/checkin" element={<CheckinCheckout />} />
        <Route path="attendance/checkouts" element={<CheckinCheckout />} />
        <Route path="/attendance" element={<AttendanceList />} />
        <Route path="/attendance/checkin" element={<CheckinCheckout />} />
        <Route path="/attendance/checkouts" element={<CheckinCheckout />} />

        {/* Overtime */}
        <Route path="overtime" element={<OvertimeList />} />
        <Route path="/overtime" element={<OvertimeList />} />

        {/* Payroll */}
        <Route path="salary-components" element={<SalaryComponents />} />
        <Route path="salary-structures" element={<SalaryStructures />} />
        <Route path="salary-assignments" element={<SalaryAssignments />} />
        <Route path="payroll" element={<PayrollEntries />} />
        <Route path="salary-slips" element={<SalarySlips />} />
        <Route path="salary-slips/:id" element={<SalarySlipDetail />} />
        <Route path="/salary-components" element={<SalaryComponents />} />
        <Route path="/salary-structures" element={<SalaryStructures />} />
        <Route path="/salary-assignments" element={<SalaryAssignments />} />
        <Route path="/payroll" element={<PayrollEntries />} />
        <Route path="/salary-slips" element={<SalarySlips />} />
        <Route path="/salary-slips/:id" element={<SalarySlipDetail />} />

        {/* Admin Route */}
        <Route path="admin" element={<Navigate to="/dashboard" replace />} />
        <Route path="/admin" element={<Navigate to="/dashboard" replace />} />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/dashboard" replace />} />
      </Route>
    </Routes>
  )
}
