import React, { useState, useEffect } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import {
  Menu,
  Bell,
  Briefcase,
  FileText,
  LogOut,
  User,
  ExternalLink,
} from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import candidateService from '../../services/erpnext/candidate'
import { useScrolled } from '../../hooks/useScrolled'

export default function CandidateNavbar({ onMenuClick }) {
  const { user, logout } = useAuth()
  const navigate = useNavigate()
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [unreadCount, setUnreadCount] = useState(0)
  const isScrolled = useScrolled(10)

  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const apps = await candidateService.getMyApplications()
        let count = 0
        apps.forEach((app) => {
          (app.notifications || []).forEach((n) => {
            if (!n.is_read) count++
          })
        })
        setUnreadCount(count)
      } catch {
        // ignore
      }
    }
    fetchNotifications()
  }, [])

  return (
    <header
      className={`h-16 sticky top-0 z-30 navbar-glass-base flex items-center justify-between px-4 sm:px-8 ${
        isScrolled
          ? 'navbar-glass-scrolled bg-white/80 backdrop-blur-md border-b border-slate-200/75 shadow-sm'
          : 'bg-white border-b border-slate-200 shadow-none'
      }`}
    >
      <div className="flex items-center gap-3">
        <button
          onClick={onMenuClick}
          className="p-2 -ml-2 rounded-lg text-slate-500 hover:text-slate-700 hover:bg-slate-100 lg:hidden"
        >
          <Menu className="w-5 h-5" />
        </button>
        <div className="flex items-center gap-2">
          <span className="font-bold text-slate-800 text-sm sm:text-base">
            Career Portal
          </span>
          <span className="hidden sm:inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold bg-sky-50 text-sky-700 border border-sky-200">
            Faircode Opportunities
          </span>
        </div>
      </div>

      <div className="flex items-center gap-2 sm:gap-4">
        <Link
          to="/candidate/jobs"
          className="hidden sm:flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-slate-700 hover:text-sky-600 hover:bg-slate-50 rounded-lg transition-colors"
        >
          <Briefcase className="w-3.5 h-3.5" />
          <span>Explore Jobs</span>
        </Link>

        <Link
          to="/candidate/applications"
          className="hidden sm:flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-slate-700 hover:text-sky-600 hover:bg-slate-50 rounded-lg transition-colors"
        >
          <FileText className="w-3.5 h-3.5" />
          <span>My Applications</span>
        </Link>

        {/* Notifications Icon */}
        <Link
          to="/candidate/notifications"
          className="relative p-2 rounded-xl text-slate-500 hover:text-slate-700 hover:bg-slate-100 transition-colors"
          title="Notifications"
        >
          <Bell className="w-4 h-4" />
          {unreadCount > 0 && (
            <span className="absolute top-1.5 right-1.5 w-2 h-2 rounded-full bg-rose-500 ring-2 ring-white animate-pulse" />
          )}
        </Link>

        {/* User profile dropdown */}
        <div className="relative">
          <button
            onClick={() => setDropdownOpen(!dropdownOpen)}
            className="flex items-center gap-2.5 p-1 rounded-xl hover:bg-slate-100 transition-colors"
          >
            <div className="w-8 h-8 rounded-lg bg-sky-600 text-white flex items-center justify-center font-bold text-xs shadow-sm">
              {user?.full_name?.charAt(0) || user?.first_name?.charAt(0) || 'C'}
            </div>
            <div className="hidden md:block text-left">
              <div className="text-xs font-bold text-slate-800 leading-tight">
                {user?.full_name || user?.first_name || 'Candidate'}
              </div>
              <div className="text-[10px] text-sky-600 font-semibold leading-tight">
                Candidate Account
              </div>
            </div>
          </button>

          {dropdownOpen && (
            <>
              <div
                className="fixed inset-0 z-40"
                onClick={() => setDropdownOpen(false)}
              />
              <div className="absolute right-0 mt-2 w-56 bg-white rounded-xl shadow-lg border border-slate-200 py-1.5 z-50">
                <div className="px-4 py-2 border-b border-slate-100">
                  <div className="text-xs font-bold text-slate-800">
                    {user?.full_name || 'Candidate'}
                  </div>
                  <div className="text-[11px] text-slate-500 truncate">
                    {user?.email || user?.name || ''}
                  </div>
                </div>

                <Link
                  to="/candidate/profile"
                  onClick={() => setDropdownOpen(false)}
                  className="w-full flex items-center gap-2 px-4 py-2 text-xs text-slate-700 hover:bg-slate-50"
                >
                  <User className="w-3.5 h-3.5 text-slate-400" />
                  <span>My Profile</span>
                </Link>

                <div className="border-t border-slate-100 my-1" />

                <button
                  onClick={() => {
                    setDropdownOpen(false)
                    logout()
                  }}
                  className="w-full flex items-center gap-2 px-4 py-2 text-xs text-rose-600 hover:bg-rose-50"
                >
                  <LogOut className="w-3.5 h-3.5 text-rose-500" />
                  <span>Sign Out</span>
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </header>
  )
}

