import React, { useEffect, useState } from 'react'
import shiftService from '../../services/erpnext/shifts'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Clock, Plus } from 'lucide-react'

export default function ShiftTypes() {
  const [shifts, setShifts] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    start_time: '09:00:00',
    end_time: '18:00:00',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const data = await shiftService.getShiftTypes()
      setShifts(data || [])
    } catch (err) {
      console.error('Failed to load shift types:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleCreateSubmit = async (e) => {
    e.preventDefault()
    try {
      await shiftService.createShiftType(formData)
      toast.success(`Shift Type "${formData.name}" created in ERPNext!`)
      setModalOpen(false)
      setFormData({ name: '', start_time: '09:00:00', end_time: '18:00:00' })
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to create Shift Type')
    }
  }

  const columns = [
    { header: 'Shift Name', accessor: 'name', className: 'font-bold text-slate-800' },
    { header: 'Start Time', accessor: 'start_time', className: 'font-mono' },
    { header: 'End Time', accessor: 'end_time', className: 'font-mono' },
    {
      header: 'Configured Duration',
      render: row => (
        <span className={`inline-flex items-center gap-1 font-semibold text-xs px-2.5 py-1 rounded-full ${
          row.total_hours >= 36 ? 'bg-indigo-50 text-indigo-700 border border-indigo-200' : 'bg-slate-100 text-slate-700'
        }`}>
          <Clock className="w-3 h-3" />
          {row.total_hours || 8} Hours {row.total_hours >= 36 ? '(Special 36H Shift)' : ''}
        </span>
      ),
    },
    {
      header: 'Auto Attendance',
      render: row => (
        <StatusBadge status={row.enable_auto_attendance ? 'Active' : 'Configured'} />
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Shift Management</h1>
          <p className="text-xs text-slate-500 mt-1">Configured Shift Types in ERPNext with custom duration support</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5 transition-all"
        >
          <Plus className="w-4 h-4" /> Create Shift Type
        </button>
      </div>

      <div className="bg-indigo-50/70 border border-indigo-100 rounded-xl p-4 flex items-start gap-3 text-xs text-indigo-900">
        <Clock className="w-5 h-5 text-indigo-600 flex-shrink-0 mt-0.5" />
        <div>
          <div className="font-bold text-indigo-950">36-Hour Shift Architecture</div>
          <div className="mt-0.5 text-indigo-800/90 leading-relaxed">
            The 36-hour shift duration is dynamically stored in ERPNext (<code className="font-mono bg-white/70 px-1 py-0.5 rounded border border-indigo-200">custom_shift_duration_hours = 36.0</code>).
            When an employee checks in, the server calculates <code className="font-mono bg-white/70 px-1 py-0.5 rounded border border-indigo-200">Shift End = Check-In + 36 Hours</code> across multi-day calendar boundaries, with automated idempotent OUT checkin and attendance generation.
          </div>
        </div>
      </div>

      <DataTable
        columns={columns}
        data={shifts}
        searchField="name"
        searchPlaceholder="Search shift types..."
        loading={loading}
      />

      {/* Create Shift Type Modal */}
      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Create New Shift Type in ERPNext">
        <form onSubmit={handleCreateSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Shift Name</label>
            <input
              type="text"
              required
              placeholder="e.g. Night Shift, 12 Hour Shift"
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Start Time</label>
              <input
                type="text"
                required
                placeholder="09:00:00"
                value={formData.start_time}
                onChange={e => setFormData({ ...formData, start_time: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none font-mono"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">End Time</label>
              <input
                type="text"
                required
                placeholder="18:00:00"
                value={formData.end_time}
                onChange={e => setFormData({ ...formData, end_time: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none font-mono"
              />
            </div>
          </div>

          <div className="p-3 bg-slate-50 rounded-lg border border-slate-100 text-xs text-slate-600">
            This will create a new <code className="font-mono">Shift Type</code> in ERPNext with auto-attendance enabled.
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Create Shift
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
