import React, { useEffect, useState } from 'react'
import applicantService from '../../services/erpnext/applicants'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { CheckCircle, XCircle, ArrowRight } from 'lucide-react'

export default function Screening() {
  const [applicants, setApplicants] = useState([])
  const [loading, setLoading] = useState(true)
  const [selectedApplicant, setSelectedApplicant] = useState(null)
  const [screeningNotes, setScreeningNotes] = useState('')
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const data = await applicantService.getApplicants()
      setApplicants(data || [])
    } catch (err) {
      console.error('Failed to load applicants for screening:', err)
      toast.error('Failed to load applicants from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleScreen = async (status) => {
    if (!selectedApplicant) return
    try {
      await applicantService.screenApplicant(selectedApplicant.name, status, screeningNotes)
      toast.success(`Applicant marked as ${status} in ERPNext`)
      setSelectedApplicant(null)
      setScreeningNotes('')
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to update screening status')
    }
  }

  const columns = [
    { header: 'Applicant', accessor: 'applicant_name', className: 'font-semibold' },
    { header: 'Position', accessor: 'job_title' },
    { header: 'Email', accessor: 'email_id' },
    { header: 'Current Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: row => (
        <button
          onClick={() => setSelectedApplicant(row)}
          className="px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
        >
          Review Screening
        </button>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Application Screening</h1>
          <p className="text-xs text-slate-500 mt-1">Screen resumes, record review notes, shortlist or reject candidates</p>
        </div>
      </div>

      <DataTable
        columns={columns}
        data={applicants}
        searchField="applicant_name"
        searchPlaceholder="Filter candidate for screening..."
        emptyMessage="No applicants for screening."
        loading={loading}
      />

      <Modal
        isOpen={!!selectedApplicant}
        onClose={() => setSelectedApplicant(null)}
        title={`Screen Candidate: ${selectedApplicant?.applicant_name}`}
      >
        <div className="space-y-4">
          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 space-y-2 text-xs">
            <div><span className="font-semibold text-slate-700">Email:</span> {selectedApplicant?.email_id}</div>
            <div><span className="font-semibold text-slate-700">Phone:</span> {selectedApplicant?.phone_number || 'N/A'}</div>
            <div><span className="font-semibold text-slate-700">Applied Job:</span> {selectedApplicant?.job_title || 'N/A'}</div>
            <div><span className="font-semibold text-slate-700">Current Status:</span> <StatusBadge status={selectedApplicant?.status} /></div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Screening Notes / Remarks</label>
            <textarea
              rows="4"
              value={screeningNotes}
              onChange={e => setScreeningNotes(e.target.value)}
              placeholder="Candidate qualifications, skill evaluation, observations..."
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            />
          </div>

          <div className="flex justify-between items-center pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => handleScreen('Rejected')}
              className="px-4 py-2 text-xs font-semibold text-rose-700 bg-rose-50 hover:bg-rose-100 border border-rose-200 rounded-lg flex items-center gap-1.5"
            >
              <XCircle className="w-4 h-4" /> Reject Candidate
            </button>
            <button
              type="button"
              onClick={() => handleScreen('Shortlisted')}
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm flex items-center gap-1.5"
            >
              <CheckCircle className="w-4 h-4" /> Shortlist for Interview
            </button>
          </div>
        </div>
      </Modal>
    </div>
  )
}
