import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import payrollService from '../../services/erpnext/payroll'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { DollarSign, PlayCircle } from 'lucide-react'

export default function PayrollEntries() {
  const [entries, setEntries] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [running, setRunning] = useState(false)
  const [formData, setFormData] = useState({
    company: 'Faircode',
    start_date: '2026-09-01',
    end_date: '2026-09-30',
    payroll_frequency: 'Monthly',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    const data = await payrollService.getPayrollEntries()
    setEntries(data)
    setLoading(false)
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleRunPayroll = async (e) => {
    e.preventDefault()
    try {
      setRunning(true)
      const res = await payrollService.generatePayrollAndSlips(formData)
      toast.success(res?.message || `Payroll Entry ${res.payroll_entry} generated with ${res.number_of_employees} employees!`)
      setModalOpen(false)
      loadData()
    } catch (err) {
      const rawMsg = err.userMessage || err.message || 'Payroll execution failed'
      const cleanMsg = rawMsg.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
      toast.error(cleanMsg)
    } finally {
      setRunning(false)
    }
  }

  const columns = [
    { header: 'Payroll ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Period', render: row => `${row.start_date} to ${row.end_date}` },
    { header: 'Employees', accessor: 'number_of_employees', className: 'font-bold' },
    { header: 'Frequency', accessor: 'payroll_frequency' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: () => (
        <Link
          to="/salary-slips"
          className="px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
        >
          View Salary Slips
        </Link>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Monthly Payroll Processing</h1>
          <p className="text-xs text-slate-500 mt-1">ERPNext Payroll Entry generation and submission</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-emerald-600 text-white text-xs font-semibold hover:bg-emerald-700 shadow-sm flex items-center gap-1.5"
        >
          <PlayCircle className="w-4 h-4" /> Run Monthly Payroll
        </button>
      </div>

      <DataTable
        columns={columns}
        data={entries}
        searchField="name"
        searchPlaceholder="Search payroll entries..."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Execute Monthly Payroll Run">
        <form onSubmit={handleRunPayroll} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Company</label>
            <input
              type="text"
              readOnly
              value={formData.company}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 bg-slate-50 outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Start Date</label>
              <input
                type="date"
                required
                value={formData.start_date}
                onChange={e => setFormData({ ...formData, start_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">End Date</label>
              <input
                type="date"
                required
                value={formData.end_date}
                onChange={e => setFormData({ ...formData, end_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>
          <div className="p-3 bg-amber-50 rounded-lg border border-amber-200 text-xs text-amber-900 leading-relaxed">
            This will fetch all active salary structure assignments, compute attendance and approved overtime hours, calculate earnings and statutory deductions (PF, ESI, LWF), and generate Salary Slips.
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={running}
              className="px-4 py-2 text-xs font-semibold text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg shadow-sm flex items-center gap-1.5"
            >
              {running ? 'Processing Payroll...' : 'Execute Payroll Entry'}
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
