import api from './client'

export const dashboardService = {
	async getMetrics() {
		try {
			const [
				employees,
				openings,
				applicants,
				interviews,
				attendance,
				leaves,
				payrollEntries,
				overtimeLogs,
			] = await Promise.all([
				api.get('/api/resource/Employee', { fields: JSON.stringify(['name', 'status', 'date_of_joining', 'department']) }),
				api.get('/api/resource/Job Opening', { fields: JSON.stringify(['name', 'status', 'planned_vacancies']) }),
				api.get('/api/resource/Job Applicant', { fields: JSON.stringify(['name', 'status']) }),
				api.get('/api/resource/Interview', { fields: JSON.stringify(['name', 'status', 'interview_type']) }),
				api.get('/api/resource/Attendance', { fields: JSON.stringify(['name', 'status', 'attendance_date']) }),
				api.get('/api/resource/Leave Application', { fields: JSON.stringify(['name', 'status', 'total_leave_days']) }),
				api.get('/api/resource/Payroll Entry', { fields: JSON.stringify(['name', 'status', 'start_date', 'end_date']) }),
				api.get('/api/resource/Employee Overtime Log', {
					fields: JSON.stringify(['name', 'employee', 'employee_name', 'date', 'ot_hours', 'overtime_amount', 'overtime_rate']),
					limit_page_length: 50,
					order_by: 'date desc'
				}).catch(() => ({ data: [] })),
			])

			const empList = employees.data || []
			const openList = openings.data || []
			const appList = applicants.data || []
			const intList = interviews.data || []
			const attList = attendance.data || []
			const leaveList = leaves.data || []
			const payList = payrollEntries.data || []
			const otList = (overtimeLogs && overtimeLogs.data) ? overtimeLogs.data : []

			// Metrics
			const totalEmployees = empList.length
			const activeEmployees = empList.filter(e => e.status === 'Active').length
			const openJobPositions = openList.filter(o => o.status === 'Open').length
			const totalApplications = appList.length
			const shortlistedCandidates = appList.filter(a => a.status === 'Shortlisted' || a.status === 'Interview Round 1').length
			const totalInterviews = intList.length
			const selectedCandidates = appList.filter(a => a.status === 'Final Selection' || a.status === 'Offer' || a.status === 'Offer Accepted' || a.status === 'Joining' || a.status === 'Employee Created').length
			const pendingAttendance = attList.filter(a => a.status === 'Pending').length
			const pendingLeaves = leaveList.filter(l => l.status === 'Applied' || l.status === 'Open').length
			const submittedPayrolls = payList.filter(p => p.status === 'Submitted').length
			const totalOvertimeHours = otList.reduce((acc, curr) => acc + (parseFloat(curr.ot_hours) || 0), 0)
			const totalOvertimeAmount = otList.reduce((acc, curr) => acc + (parseFloat(curr.overtime_amount) || 0), 0)

			// Department distribution
			const deptCounts = {}
			for (const e of empList) {
				const d = e.department || 'Unassigned'
				deptCounts[d] = (deptCounts[d] || 0) + 1
			}

			// Recruitment Pipeline counts
			const pipelineStages = [
				{ stage: 'Job Openings', count: openList.length },
				{ stage: 'Applications', count: appList.length },
				{ stage: 'Screening', count: appList.filter(a => ['Open', 'Application Received', 'Screening'].includes(a.status)).length },
				{ stage: 'Shortlisted', count: appList.filter(a => a.status === 'Shortlisted').length },
				{ stage: 'Interview R1', count: intList.filter(i => i.interview_type?.includes('1') || i.interview_type?.includes('Round 1')).length },
				{ stage: 'Interview R2', count: intList.filter(i => i.interview_type?.includes('2') || i.interview_type?.includes('Round 2')).length },
				{ stage: 'Selected', count: selectedCandidates },
				{ stage: 'Employees Created', count: appList.filter(a => a.status === 'Employee Created').length },
			]

			// Attendance status breakdown
			const attendanceCounts = {
				Present: attList.filter(a => a.status === 'Present').length,
				Pending: pendingAttendance,
				Absent: attList.filter(a => a.status === 'Absent').length,
				'On Leave': attList.filter(a => a.status === 'On Leave').length,
			}

			// Leave status breakdown
			const leaveCounts = {
				Approved: leaveList.filter(l => l.status === 'Approved').length,
				Pending: pendingLeaves,
				Rejected: leaveList.filter(l => l.status === 'Rejected').length,
			}

			return {
				totalEmployees,
				activeEmployees,
				openJobPositions,
				totalApplications,
				shortlistedCandidates,
				totalInterviews,
				selectedCandidates,
				pendingAttendance,
				pendingLeaves,
				payrollStatus: submittedPayrolls > 0 ? 'Submitted' : (payList.length > 0 ? 'Draft' : 'Not Generated'),
				departmentDistribution: deptCounts,
				recruitmentPipeline: pipelineStages,
				attendanceSummary: attendanceCounts,
				leaveSummary: leaveCounts,
				totalPayrollEntries: payList.length,
				totalOvertimeHours,
				totalOvertimeAmount: totalOvertimeAmount.toFixed(2),
				recentOvertimeLogs: otList.slice(0, 5),
			}
		} catch (err) {
			console.error('Error fetching dashboard metrics', err)
			return {
				totalEmployees: 0,
				activeEmployees: 0,
				openJobPositions: 0,
				totalApplications: 0,
				shortlistedCandidates: 0,
				totalInterviews: 0,
				selectedCandidates: 0,
				pendingAttendance: 0,
				pendingLeaves: 0,
				payrollStatus: 'N/A',
				departmentDistribution: {},
				recruitmentPipeline: [],
				attendanceSummary: {},
				leaveSummary: {},
				totalPayrollEntries: 0,
			}
		}
	},
}

export default dashboardService

