import { useState, useEffect } from 'react'

/**
 * Custom hook to detect when window or page container has scrolled past threshold.
 * @param {number} threshold - Scroll offset threshold in pixels (default: 10)
 * @returns {boolean} - true if scrolled past threshold, false otherwise
 */
export function useScrolled(threshold = 10) {
  const [isScrolled, setIsScrolled] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      const scrollY =
        window.scrollY ||
        window.pageYOffset ||
        document.documentElement.scrollTop ||
        document.body.scrollTop ||
        0
      setIsScrolled(scrollY > threshold)
    }

    // Check initial position on mount
    handleScroll()

    // Listen to scroll events (capture: true catches any nested scrollable elements as well)
    window.addEventListener('scroll', handleScroll, { passive: true, capture: true })
    return () => {
      window.removeEventListener('scroll', handleScroll, { capture: true })
    }
  }, [threshold])

  return isScrolled
}

export default useScrolled

