import React, { useEffect, useState } from 'react'
import applicantService from '../../services/erpnext/applicants'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { FileCheck, Plus } from 'lucide-react'

export default function JobOffers() {
  const [offers, setOffers] = useState([])
  const [applicants, setApplicants] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    applicant: '',
    designation: 'Software Developer',
    department: 'Information Technology',
    company: 'Faircode',
    offer_date: new Date().toISOString().split('T')[0],
    salary: 40000,
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [offerList, appList] = await Promise.all([
        applicantService.getJobOffers(),
        applicantService.getApplicants(),
      ])
      setOffers(offerList || [])
      setApplicants(appList || [])
      if (appList && appList.length > 0 && !formData.applicant) {
        setFormData(prev => ({ ...prev, applicant: appList[0].name }))
      }
    } catch (err) {
      console.error('Failed to load Job Offers:', err)
      toast.error('Failed to load job offers from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await applicantService.createJobOffer(formData)
      toast.success('Job Offer generated in ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to create Job Offer')
    }
  }

  const columns = [
    { header: 'Offer ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Candidate', accessor: 'applicant_name', className: 'font-semibold' },
    { header: 'Designation', accessor: 'designation' },
    { header: 'Offer Date', accessor: 'offer_date' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Job Offers</h1>
          <p className="text-xs text-slate-500 mt-1">Formal job offers issued to selected candidates in ERPNext</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Issue Offer
        </button>
      </div>

      <DataTable
        columns={columns}
        data={offers}
        searchField="applicant_name"
        searchPlaceholder="Search offers..."
        emptyMessage="No job offers found."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Issue Formal Job Offer">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Selected Candidate</label>
            <select
              value={formData.applicant}
              onChange={e => setFormData({ ...formData, applicant: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            >
              {applicants.map(app => (
                <option key={app.name} value={app.name}>{app.applicant_name} ({app.email_id})</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Offered Designation</label>
              <select
                value={formData.designation}
                onChange={e => setFormData({ ...formData, designation: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              >
                <option value="Software Developer">Software Developer</option>
                <option value="HR Executive">HR Executive</option>
                <option value="Accountant">Accountant</option>
                <option value="Operations Executive">Operations Executive</option>
                <option value="Manager">Manager</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Department</label>
              <select
                value={formData.department}
                onChange={e => setFormData({ ...formData, department: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              >
                <option value="Information Technology">Information Technology</option>
                <option value="Human Resources">Human Resources</option>
                <option value="Finance">Finance</option>
                <option value="Operations">Operations</option>
                <option value="Administration">Administration</option>
              </select>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Base Monthly Salary (₹)</label>
              <input
                type="number"
                required
                value={formData.salary}
                onChange={e => setFormData({ ...formData, salary: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Offer Date</label>
              <input
                type="date"
                required
                value={formData.offer_date}
                onChange={e => setFormData({ ...formData, offer_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Create Job Offer
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
