import React, { useEffect, useState } from 'react'
import { Clock, Calendar, ShieldCheck, CheckCircle2, RefreshCw, AlertCircle, Layers } from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import shiftService from '../../services/erpnext/shifts'
import StatusBadge from '../../components/common/StatusBadge'

export default function UserShift() {
  const { user, employee } = useAuth()
  const empId = employee?.name || ''

  const [shiftStatus, setShiftStatus] = useState(null)
  const [assignments, setAssignments] = useState([])
  const [loading, setLoading] = useState(true)

  const loadShiftData = async () => {
    if (!empId) {
      setLoading(false)
      return
    }
    setLoading(true)
    try {
      const [status, assignList] = await Promise.all([
        shiftService.getEmployeeShiftStatus(empId).catch(() => null),
        shiftService.getShiftAssignments({ employee: empId }).catch(() => []),
      ])
      setShiftStatus(status)
      setAssignments(assignList || [])
    } catch (err) {
      console.error('Failed to load shift details:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadShiftData()
  }, [empId])

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">My Shift Schedule</h1>
          <p className="text-xs text-slate-500 mt-1">
            Current work schedule and shift assignment details for {employee?.employee_name || user?.full_name || 'Employee'} {empId ? `(${empId})` : ''}
          </p>
        </div>
        <button
          onClick={loadShiftData}
          disabled={loading}
          className="px-3.5 py-2 rounded-xl bg-white border border-slate-200 text-slate-700 text-xs font-semibold shadow-sm hover:bg-slate-50 transition-colors flex items-center gap-2 self-start sm:self-auto"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          <span>Refresh</span>
        </button>
      </div>

      {/* Active Shift Card */}
      <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-start gap-4">
            <div className="p-4 rounded-2xl bg-indigo-50 text-indigo-600 shrink-0 border border-indigo-100">
              <Clock className="w-8 h-8" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-xl font-bold text-slate-800">
                  {shiftStatus?.shift || 'No Shift Assigned'}
                </h2>
                <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-indigo-100 text-indigo-700 border border-indigo-200">
                  {shiftStatus?.shift ? 'Assigned Shift' : 'Unassigned'}
                </span>
              </div>
              <p className="text-xs text-slate-500 mt-1">
                Work Schedule Architecture • Automated Attendance Reconciliation
              </p>

              <div className="flex flex-wrap items-center gap-4 mt-4 text-xs font-medium text-slate-600">
                <div className="flex items-center gap-1.5 bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100">
                  <span className="text-slate-400">Duration:</span>
                  <span className="font-bold text-indigo-600">{shiftStatus?.duration_hours ? `${shiftStatus.duration_hours} Hours` : '-'}</span>
                </div>
                <div className="flex items-center gap-1.5 bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100">
                  <span className="text-slate-400">Schedule:</span>
                  <span className="font-semibold text-slate-800">{shiftStatus?.shift ? 'Configured in ERPNext' : 'Not Configured'}</span>
                </div>
                <div className="flex items-center gap-1.5 bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100 text-emerald-700">
                  <CheckCircle2 className="w-3.5 h-3.5" />
                  <span>Auto Attendance Configured</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Shift Rules & Policies */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
          <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 pb-2 border-b border-slate-100 flex items-center gap-2">
            <Layers className="w-4 h-4 text-indigo-600" />
            <span>36-Hour Continuous Shift Architecture</span>
          </h3>
          <ul className="space-y-3 text-xs text-slate-600 leading-relaxed">
            <li className="flex items-start gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-600 mt-1.5 shrink-0" />
              <span>
                <strong>Dynamic Checkout Timestamp:</strong> When an employee registers an IN checkin, the backend automatically calculates the expected checkout boundary as <code className="bg-slate-100 px-1 py-0.5 rounded text-indigo-600 font-mono">IN + 36 Hours</code>.
              </span>
            </li>
            <li className="flex items-start gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-600 mt-1.5 shrink-0" />
              <span>
                <strong>Multi-Day Continuity:</strong> The shift begins on Day 1 (e.g. 09:00 AM) and concludes on Day 2 (e.g. 09:00 PM). The attendance record is anchored to the shift start date.
              </span>
            </li>
            <li className="flex items-start gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-600 mt-1.5 shrink-0" />
              <span>
                <strong>Automated OUT Logging:</strong> The background processor creates an automatic OUT log with device ID <code className="bg-slate-100 px-1 py-0.5 rounded text-slate-700 font-mono">Auto 36H Checkout</code> when the shift duration elapses.
              </span>
            </li>
            <li className="flex items-start gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-indigo-600 mt-1.5 shrink-0" />
              <span>
                <strong>Strict Idempotency:</strong> Repeated runs of the processor never produce duplicate check-out entries or duplicate attendance documents.
              </span>
            </li>
          </ul>
        </div>

        {/* Shift Assignment History */}
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
          <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 pb-2 border-b border-slate-100 flex items-center gap-2">
            <Calendar className="w-4 h-4 text-indigo-600" />
            <span>ERPNext Shift Assignment Records</span>
          </h3>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-100 text-slate-400 font-semibold uppercase tracking-wider">
                  <th className="pb-2.5">Shift Type</th>
                  <th className="pb-2.5">Start Date</th>
                  <th className="pb-2.5">End Date</th>
                  <th className="pb-2.5">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {assignments.length === 0 ? (
                  <tr>
                    <td colSpan="4" className="py-6 text-center text-slate-400">
                      No shift assignment records found.
                    </td>
                  </tr>
                ) : (
                  assignments.map((sa, idx) => (
                    <tr key={idx} className="hover:bg-slate-50/60">
                      <td className="py-3 font-semibold text-slate-800">{sa.shift_type}</td>
                      <td className="py-3 font-mono text-slate-600">{sa.start_date}</td>
                      <td className="py-3 font-mono text-slate-500">{sa.end_date || 'Ongoing'}</td>
                      <td className="py-3">
                        <StatusBadge status={sa.status || 'Active'} />
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  )
}

