import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import {
  Briefcase,
  MapPin,
  Clock,
  Users,
  Search,
  CheckCircle2,
  ArrowRight,
  Building,
  Calendar,
} from 'lucide-react'
import candidateService from '../../services/erpnext/candidate'

export default function CandidateJobs() {
  const [openings, setOpenings] = useState([])
  const [myApplications, setMyApplications] = useState([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedDepartment, setSelectedDepartment] = useState('All')

  const loadData = async () => {
    setLoading(true)
    try {
      const [jobs, apps] = await Promise.all([
        candidateService.getActiveJobOpenings(),
        candidateService.getMyApplications().catch(() => []),
      ])
      setOpenings(jobs || [])
      setMyApplications(apps || [])
    } catch (err) {
      console.error('Failed to load job openings:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const departments = ['All', ...new Set(openings.map((j) => j.department).filter(Boolean))]

  const availableJobs = openings.filter(
    (job) => job.status === 'Open' && (job.planned_vacancies === undefined || job.planned_vacancies > 0)
  )

  const filteredJobs = availableJobs.filter((job) => {
    const matchesSearch =
      (job.job_title || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (job.department || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (job.description || '').toLowerCase().includes(searchTerm.toLowerCase())
    const matchesDept = selectedDepartment === 'All' || job.department === selectedDepartment
    return matchesSearch && matchesDept
  })

  // Check if candidate has applied to a specific job
  const getAppliedApplication = (jobName) => {
    return myApplications.find((app) => app.job_title === jobName)
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div>
        <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Available Job Openings</h1>
        <p className="text-xs text-slate-500 mt-1">
          Explore current career opportunities at Faircode. Apply directly from your candidate portal.
        </p>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm flex flex-col sm:flex-row items-center gap-3">
        <div className="relative flex-1 w-full">
          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Search by job title, department, skills..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-4 py-2 text-xs rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500/20 focus:border-sky-500"
          />
        </div>

        <div className="w-full sm:w-auto">
          <select
            value={selectedDepartment}
            onChange={(e) => setSelectedDepartment(e.target.value)}
            className="w-full sm:w-auto px-3 py-2 text-xs rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500/20 focus:border-sky-500 bg-white"
          >
            {departments.map((dept) => (
              <option key={dept} value={dept}>
                {dept === 'All' ? 'All Departments' : dept}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Jobs Grid */}
      {loading ? (
        <div className="text-center py-16 text-slate-400 text-xs">
          <div className="w-8 h-8 border-2 border-sky-500 border-r-transparent rounded-full animate-spin mx-auto mb-3" />
          <span>Loading available job openings from ERPNext...</span>
        </div>
      ) : filteredJobs.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-2xl border border-dashed border-slate-200 p-8">
          <Briefcase className="w-10 h-10 text-slate-300 mx-auto mb-3" />
          <h3 className="text-sm font-bold text-slate-700">No matching job openings found</h3>
          <p className="text-xs text-slate-400 mt-1">Try clearing your search query or check back soon.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {filteredJobs.map((job) => {
            const applied = getAppliedApplication(job.name)
            const isDeactivated = Boolean(
              job.is_deactivated_for_candidate ||
              (applied && (
                applied.interview_1_result === 'Rejected' ||
                applied.interview_2_result === 'Rejected' ||
                applied.final_result === 'Rejected' ||
                applied.status === 'Interview 1 Rejected' ||
                applied.status === 'Interview 2 Rejected' ||
                applied.status === 'Final Rejected'
              ))
            )

            return (
              <div
                key={job.name}
                className={`bg-white rounded-2xl border p-6 shadow-sm hover:shadow-md transition-all flex flex-col justify-between space-y-4 ${
                  isDeactivated ? 'border-rose-200 bg-rose-50/20' : 'border-slate-200'
                }`}
              >
                <div className="space-y-3">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <span className="text-[10px] font-mono text-sky-600 font-semibold block mb-0.5">
                        {job.name}
                      </span>
                      <h2 className="text-base font-bold text-slate-800 leading-tight">
                        {job.job_title}
                      </h2>
                    </div>
                    {isDeactivated ? (
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-rose-50 text-rose-700 border border-rose-200 shrink-0">
                        Deactivated for Role
                      </span>
                    ) : (
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200 shrink-0">
                        {job.employment_type || 'Full-time'}
                      </span>
                    )}
                  </div>

                  {/* Metadata tags */}
                  <div className="flex flex-wrap items-center gap-3 text-xs text-slate-500">
                    <div className="flex items-center gap-1">
                      <Building className="w-3.5 h-3.5 text-slate-400" />
                      <span>{job.department || 'Engineering'}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <MapPin className="w-3.5 h-3.5 text-slate-400" />
                      <span>{job.location || 'Kochi, Kerala / Hybrid'}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Users className="w-3.5 h-3.5 text-slate-400" />
                      <span>
                        {(job.planned_vacancies !== undefined && job.planned_vacancies <= 0) || job.status === 'Closed'
                          ? '0 Openings (Filled)'
                          : `${job.planned_vacancies || 1} Openings`}
                      </span>
                    </div>
                  </div>

                  {/* Description */}
                  <p className="text-xs text-slate-600 line-clamp-3 leading-relaxed">
                    {job.description ||
                      'Join our forward-thinking team at Faircode to build cutting-edge solutions with modern web frameworks, ERPNext, and agile development methodologies.'}
                  </p>
                </div>

                {/* Card Action */}
                <div className="pt-3 border-t border-slate-100 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                  <div className="text-[11px] text-slate-400">
                    {job.posted_on ? `Posted on: ${job.posted_on}` : 'Actively Hiring'}
                  </div>

                  {isDeactivated ? (
                    <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                      <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl bg-rose-50 text-rose-700 font-bold text-xs border border-rose-200">
                        <span>Not Eligible (Not Selected)</span>
                      </span>
                      <span className="text-[10px] text-slate-500 italic">
                        Eligible to apply for other roles only
                      </span>
                    </div>
                  ) : applied ? (
                    <div className="flex items-center gap-2">
                      <span className="inline-flex items-center gap-1 text-xs font-semibold text-emerald-600 bg-emerald-50 px-2.5 py-1 rounded-lg border border-emerald-200">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        <span>Applied ({applied.status})</span>
                      </span>
                      <Link
                        to="/candidate/applications"
                        className="px-3 py-1 text-xs font-semibold text-sky-600 hover:text-sky-700"
                      >
                        View Status
                      </Link>
                    </div>
                  ) : ((job.planned_vacancies !== undefined && job.planned_vacancies <= 0) || job.status === 'Closed') ? (
                    <span className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-slate-100 text-slate-500 font-semibold text-xs border border-slate-200">
                      <span>Position Filled</span>
                    </span>
                  ) : (
                    <Link
                      to={`/candidate/apply/${encodeURIComponent(job.name)}`}
                      className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-semibold text-xs shadow-sm hover:shadow-md transition-all"
                    >
                      <span>Apply Now</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </Link>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

