import React, { useEffect, useState } from 'react'
import shiftService from '../../services/erpnext/shifts'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus } from 'lucide-react'

export default function ShiftAssignments() {
  const [assignments, setAssignments] = useState([])
  const [employees, setEmployees] = useState([])
  const [shifts, setShifts] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    employee: '',
    shift_type: '36 Hour Shift',
    start_date: new Date().toISOString().split('T')[0],
    end_date: '',
    company: 'Faircode',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    const [aList, empList, sList] = await Promise.all([
      shiftService.getShiftAssignments(),
      employeeService.getEmployees(),
      shiftService.getShiftTypes(),
    ])
    setAssignments(aList)
    setEmployees(empList)
    setShifts(sList)
    if (empList.length > 0 && !formData.employee) {
      setFormData(prev => ({ ...prev, employee: empList[0].name }))
    }
    setLoading(false)
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await shiftService.createShiftAssignment(formData)
      toast.success('Shift assigned to employee in ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Shift assignment failed')
    }
  }

  const columns = [
    { header: 'Assignment ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Employee', accessor: 'employee_name', className: 'font-semibold' },
    { header: 'Shift Type', accessor: 'shift_type' },
    { header: 'Start Date', accessor: 'start_date' },
    { header: 'End Date', render: row => row.end_date || 'Ongoing' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Shift Assignments</h1>
          <p className="text-xs text-slate-500 mt-1">Assign employees to regular or 36-hour shifts</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Assign Shift
        </button>
      </div>

      <DataTable
        columns={columns}
        data={assignments}
        searchField="employee_name"
        searchPlaceholder="Search shift assignments..."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Assign Shift to Employee">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Employee</label>
            <select
              value={formData.employee}
              onChange={e => setFormData({ ...formData, employee: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {employees.map(emp => (
                <option key={emp.name} value={emp.name}>{emp.employee_name} ({emp.name})</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Shift Type</label>
            <select
              value={formData.shift_type}
              onChange={e => setFormData({ ...formData, shift_type: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {shifts.map(st => (
                <option key={st.name} value={st.name}>{st.name} ({st.total_hours || 8} hrs)</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Start Date</label>
              <input
                type="date"
                required
                value={formData.start_date}
                onChange={e => setFormData({ ...formData, start_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">End Date (Optional)</label>
              <input
                type="date"
                value={formData.end_date}
                onChange={e => setFormData({ ...formData, end_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Confirm Assignment
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
