import React, { useEffect, useState } from 'react'
import { Users, Search, RefreshCw, Mail, Phone, UserCheck, ShieldCheck } from 'lucide-react'
import candidateService from '../../services/erpnext/candidate'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import { useToast } from '../../components/common/Toast'

export default function CandidateList() {
  const [candidates, setCandidates] = useState([])
  const [loading, setLoading] = useState(true)
  const toast = useToast()

  const loadCandidates = async () => {
    setLoading(true)
    try {
      const data = await candidateService.getCandidatesList()
      setCandidates(data || [])
    } catch (err) {
      console.error('Failed to load candidate list:', err)
      toast.error('Failed to load candidates from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadCandidates()
  }, [])

  const columns = [
    {
      header: 'Candidate ID',
      accessor: 'name',
      className: 'font-mono text-xs font-bold text-indigo-600',
    },
    {
      header: 'Candidate Name',
      accessor: 'candidate_name',
      className: 'font-semibold text-slate-800',
    },
    {
      header: 'Email',
      accessor: 'email',
      render: (row) => (
        <span className="inline-flex items-center gap-1.5 text-slate-600 text-xs">
          <Mail className="w-3.5 h-3.5 text-slate-400" />
          <span>{row.email}</span>
        </span>
      ),
    },
    {
      header: 'Phone',
      accessor: 'phone',
      render: (row) => (
        <span className="inline-flex items-center gap-1.5 text-slate-600 text-xs">
          <Phone className="w-3.5 h-3.5 text-slate-400" />
          <span>{row.phone || '—'}</span>
        </span>
      ),
    },
    {
      header: 'Status',
      accessor: 'status',
      render: (row) => <StatusBadge status={row.status || 'Active'} />,
    },
    {
      header: 'Related User Account',
      accessor: 'user',
      render: (row) => (
        <span className="inline-flex items-center gap-1.5 text-xs text-indigo-700 font-medium bg-indigo-50/80 px-2 py-1 rounded-md border border-indigo-200/50">
          <UserCheck className="w-3.5 h-3.5 text-indigo-600" />
          <span>{row.user || row.email}</span>
        </span>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Candidates</h1>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-semibold bg-indigo-100 text-indigo-800">
              {candidates.length} Registered
            </span>
          </div>
          <p className="text-xs text-slate-500 mt-1">
            Registered candidates synchronized from ERPNext Candidate &amp; User DocTypes
          </p>
        </div>

        <button
          onClick={loadCandidates}
          disabled={loading}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-slate-700 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 shadow-sm transition-colors"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          <span>Refresh</span>
        </button>
      </div>

      {/* Candidates Table */}
      <DataTable
        columns={columns}
        data={candidates}
        searchField="candidate_name"
        searchPlaceholder="Search candidates by name, email, or ID..."
        emptyMessage="No registered candidates found in ERPNext."
        loading={loading}
      />
    </div>
  )
}

