import React, { useEffect, useState } from 'react'
import { Calendar, Clock, CheckCircle2, RefreshCw, Layers } from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import attendanceService from '../../services/erpnext/attendance'
import StatusBadge from '../../components/common/StatusBadge'
import StatCard from '../../components/common/StatCard'
import DataTable from '../../components/common/DataTable'

export default function UserAttendance() {
  const { user, employee } = useAuth()
  const empId = employee?.name || ''

  const [attendance, setAttendance] = useState([])
  const [loading, setLoading] = useState(true)

  const loadAttendance = async () => {
    if (!empId) {
      setLoading(false)
      return
    }
    setLoading(true)
    try {
      const data = await attendanceService.getAttendance({ employee: empId }, 100)
      setAttendance(data || [])
    } catch (err) {
      console.error('Failed to load attendance:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadAttendance()
  }, [empId])

  const presentCount = attendance.filter(a => a.status === 'Present').length
  const totalHours = attendance.reduce((sum, a) => sum + (parseFloat(a.working_hours) || 0), 0)

  const columns = [
    {
      header: 'Attendance Date',
      render: (row) => (
        <div className="font-semibold text-slate-800 flex items-center gap-2">
          <Calendar className="w-3.5 h-3.5 text-indigo-600" />
          <span>{row.attendance_date}</span>
        </div>
      ),
    },
    {
      header: 'Status',
      render: (row) => <StatusBadge status={row.status} />,
    },
    {
      header: 'Working Hours',
      render: (row) => (
        <div className="font-mono font-bold text-slate-700">
          {row.working_hours ? `${row.working_hours} hrs` : '-'}
        </div>
      ),
    },
    {
      header: 'Shift',
      render: (row) => <span className="text-slate-600 font-medium">{row.shift || '-'}</span>,
    },
    {
      header: 'In Time',
      render: (row) => (
        <span className="font-mono text-slate-600 text-xs">
          {row.in_time || '-'}
        </span>
      ),
    },
    {
      header: 'Out Time',
      render: (row) => (
        <span className="font-mono text-slate-600 text-xs">
          {row.out_time || '-'}
        </span>
      ),
    },
    {
      header: 'Doc ID',
      render: (row) => <span className="font-mono text-[11px] text-slate-400">{row.name}</span>,
    },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">My Attendance</h1>
          <p className="text-xs text-slate-500 mt-1">
            Complete attendance log and working hours breakdown for {employee?.employee_name || user?.full_name || 'Employee'} {empId ? `(${empId})` : ''}
          </p>
        </div>
        <button
          onClick={loadAttendance}
          disabled={loading}
          className="px-3.5 py-2 rounded-xl bg-white border border-slate-200 text-slate-700 text-xs font-semibold shadow-sm hover:bg-slate-50 transition-colors flex items-center gap-2 self-start sm:self-auto"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          <span>Refresh Records</span>
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard
          title="Present Records"
          value={presentCount}
          subtitle="Total verified Present shifts"
          icon={CheckCircle2}
          color="emerald"
        />
        <StatCard
          title="Total Logged Hours"
          value={`${totalHours.toFixed(1)} hrs`}
          subtitle="Cumulative shift hours"
          icon={Clock}
          color="indigo"
        />
        <StatCard
          title="Recorded Days"
          value={attendance.length}
          subtitle="Total attendance logs in ERPNext"
          icon={Layers}
          color="purple"
        />
      </div>

      {/* Attendance Table */}
      <DataTable
        columns={columns}
        data={attendance}
        searchPlaceholder="Filter by date or status..."
        loading={loading}
        emptyMessage="No attendance records found for your employee profile."
      />
    </div>
  )
}

