import React from 'react'
import { NavLink } from 'react-router-dom'
import {
  LayoutDashboard,
  Briefcase,
  FileText,
  Video,
  Bell,
  User,
  LogOut,
  ChevronRight,
  CheckCircle,
} from 'lucide-react'
import { useAuth } from '../../context/AuthContext'

export default function CandidateSidebar({ isOpen, onClose }) {
  const { user, logout } = useAuth()

  const navSections = [
    {
      title: 'Candidate Portal',
      items: [
        { label: 'Dashboard', to: '/candidate/dashboard', icon: LayoutDashboard },
        { label: 'Job Openings', to: '/candidate/jobs', icon: Briefcase },
        { label: 'My Applications', to: '/candidate/applications', icon: FileText },
        { label: 'Interviews & Calls', to: '/candidate/interviews', icon: Video },
      ],
    },
    {
      title: 'Account & Alerts',
      items: [
        { label: 'Notifications', to: '/candidate/notifications', icon: Bell },
        { label: 'My Profile', to: '/candidate/profile', icon: User },
      ],
    },
  ]

  return (
    <>
      {/* Mobile overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-slate-900/50 backdrop-blur-sm lg:hidden"
          onClick={onClose}
        />
      )}

      <aside
        className={`fixed top-0 bottom-0 left-0 z-40 w-64 bg-slate-900 text-slate-300 flex flex-col transition-transform duration-200 ease-in-out lg:translate-x-0 ${
          isOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {/* Brand header */}
        <div className="h-16 flex items-center px-6 border-b border-slate-800 gap-3">
          <div className="w-8 h-8 rounded-lg bg-sky-600 flex items-center justify-center text-white font-black text-lg shadow-md shadow-sky-500/20">
            F
          </div>
          <div>
            <div className="font-bold text-white text-base leading-tight tracking-tight">Faircode</div>
            <div className="text-[11px] text-sky-400 font-semibold tracking-wider uppercase flex items-center gap-1">
              <span className="w-1.5 h-1.5 rounded-full bg-sky-400 animate-pulse" />
              Candidate Portal
            </div>
          </div>
        </div>

        {/* Candidate quick card */}
        <div className="px-4 py-3 mx-3 mt-3 rounded-xl bg-slate-800/60 border border-slate-700/60 flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-sky-600/30 text-sky-400 flex items-center justify-center font-bold text-sm border border-sky-500/30">
            {user?.full_name?.charAt(0) || user?.first_name?.charAt(0) || 'C'}
          </div>
          <div className="min-w-0 flex-1">
            <div className="text-xs font-bold text-white truncate">
              {user?.full_name || user?.first_name || 'Candidate'}
            </div>
            <div className="text-[11px] text-slate-400 truncate">
              {user?.email || user?.name || ''}
            </div>
            <div className="text-[10px] text-sky-400 flex items-center gap-1 mt-0.5">
              <CheckCircle className="w-3 h-3 text-sky-400" /> Verified Candidate
            </div>
          </div>
        </div>

        {/* Navigation list */}
        <div className="flex-1 overflow-y-auto py-3 px-3 space-y-5 sidebar-scroll sidebar-scroll-candidate">
          {navSections.map((sec, secIdx) => (
            <div key={secIdx}>
              <div className="px-3 text-[10px] font-bold uppercase tracking-wider text-slate-500 mb-1">
                {sec.title}
              </div>
              <div className="space-y-0.5">
                {sec.items.map((item) => {
                  const Icon = item.icon
                  return (
                    <NavLink
                      key={item.to}
                      to={item.to}
                      onClick={onClose}
                      className={({ isActive }) =>
                        `flex items-center justify-between px-3 py-2 rounded-xl text-xs font-medium transition-all ${
                          isActive
                            ? 'bg-sky-600 text-white font-semibold shadow-md shadow-sky-600/20'
                            : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/60'
                        }`
                      }
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <Icon className="w-4 h-4 shrink-0" />
                        <span className="truncate">{item.label}</span>
                      </div>
                      <ChevronRight className="w-3.5 h-3.5 opacity-50 shrink-0" />
                    </NavLink>
                  )
                })}
              </div>
            </div>
          ))}
        </div>

        {/* Footer logout */}
        <div className="p-3 border-t border-slate-800">
          <button
            onClick={logout}
            className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-medium text-rose-400 hover:bg-rose-500/10 hover:text-rose-300 transition-colors"
          >
            <LogOut className="w-4 h-4 shrink-0" />
            <span>Sign Out</span>
          </button>
        </div>
      </aside>
    </>
  )
}

