import React, { useEffect, useState } from 'react'
import interviewService from '../../services/erpnext/interviews'
import applicantService from '../../services/erpnext/applicants'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Calendar, Plus, CheckCircle2, XCircle } from 'lucide-react'

export default function Interviews() {
  const [interviews, setInterviews] = useState([])
  const [applicants, setApplicants] = useState([])
  const [loading, setLoading] = useState(true)
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false)
  const [evalModalOpen, setEvalModalOpen] = useState(false)
  const [selectedInterview, setSelectedInterview] = useState(null)

  const [scheduleForm, setScheduleForm] = useState({
    applicant: '',
    interview_type: 'Round 1',
    scheduled_on: new Date().toISOString().split('T')[0],
    from_time: '10:00:00',
    to_time: '11:00:00',
  })

  const [evalForm, setEvalForm] = useState({
    technical_score: 8,
    communication_score: 8,
    overall_score: 8,
    feedback: 'Strong technical foundations and clear communication.',
    recommendation: 'Hire',
  })

  const toast = useToast()

  const applicantMap = React.useMemo(() => {
    const map = {}
    applicants.forEach(app => {
      map[app.name] = app.applicant_name
    })
    return map
  }, [applicants])

  const loadData = async () => {
    setLoading(true)
    try {
      const [intList, appList] = await Promise.all([
        interviewService.getInterviews(),
        applicantService.getApplicants(),
      ])
      setInterviews(intList || [])
      setApplicants(appList || [])
      if (appList && appList.length > 0 && !scheduleForm.applicant) {
        setScheduleForm(prev => ({ ...prev, applicant: appList[0].name }))
      }
    } catch (err) {
      console.error('Failed to load Interviews:', err)
      toast.error('Failed to load interviews from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleScheduleSubmit = async (e) => {
    e.preventDefault()
    try {
      await interviewService.scheduleInterview({
        applicant: scheduleForm.applicant,
        job_applicant: scheduleForm.applicant,
        ...scheduleForm,
      })
      toast.success('Interview scheduled in ERPNext')
      setScheduleModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to schedule interview')
    }
  }

  const handleEvalSubmit = async (e) => {
    e.preventDefault()
    try {
      await interviewService.submitEvaluation({
        interview_name: selectedInterview.name,
        ...evalForm,
      })
      toast.success('Interview evaluation recorded in ERPNext')
      setEvalModalOpen(false)
      setSelectedInterview(null)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to submit evaluation')
    }
  }

  const columns = [
    { header: 'Interview ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    {
      header: 'Candidate',
      render: row => applicantMap[row.job_applicant] ? `${applicantMap[row.job_applicant]} (${row.job_applicant})` : (row.job_applicant || '-'),
      className: 'font-semibold',
    },
    { header: 'Round / Type', accessor: 'interview_type' },
    { header: 'Date', accessor: 'scheduled_on' },
    { header: 'Time', render: row => `${row.from_time || '10:00'} - ${row.to_time || '11:00'}` },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Evaluation',
      render: row => (
        <button
          onClick={() => { setSelectedInterview(row); setEvalModalOpen(true) }}
          className="px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
        >
          Record Score
        </button>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Interview Management</h1>
          <p className="text-xs text-slate-500 mt-1">Multi-round evaluation (Round 1, Round 2, HR Interview) stored in ERPNext</p>
        </div>
        <button
          onClick={() => setScheduleModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Schedule Interview
        </button>
      </div>

      <DataTable
        columns={columns}
        data={interviews}
        searchField="job_applicant"
        searchPlaceholder="Search interviews..."
        emptyMessage="No interviews scheduled."
        loading={loading}
      />

      {/* Schedule Modal */}
      <Modal isOpen={scheduleModalOpen} onClose={() => setScheduleModalOpen(false)} title="Schedule Interview Round">
        <form onSubmit={handleScheduleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Candidate</label>
            <select
              value={scheduleForm.applicant}
              onChange={e => setScheduleForm({ ...scheduleForm, applicant: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            >
              {applicants.map(app => (
                <option key={app.name} value={app.name}>{app.applicant_name} ({app.name})</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Interview Round</label>
              <select
                value={scheduleForm.interview_type}
                onChange={e => setScheduleForm({ ...scheduleForm, interview_type: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              >
                <option value="Round 1">Round 1 (Technical Interview)</option>
                <option value="Round 2">Round 2 (Managerial Interview)</option>
                <option value="HR Round">HR Round (Final Interview)</option>
                <option value="Technical Round">Technical Round</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Date</label>
              <input
                type="date"
                required
                value={scheduleForm.scheduled_on}
                onChange={e => setScheduleForm({ ...scheduleForm, scheduled_on: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">From Time</label>
              <input
                type="time"
                value={scheduleForm.from_time}
                onChange={e => setScheduleForm({ ...scheduleForm, from_time: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">To Time</label>
              <input
                type="time"
                value={scheduleForm.to_time}
                onChange={e => setScheduleForm({ ...scheduleForm, to_time: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              />
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setScheduleModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Schedule Interview
            </button>
          </div>
        </form>
      </Modal>

      {/* Evaluation Modal */}
      <Modal
        isOpen={evalModalOpen}
        onClose={() => setEvalModalOpen(false)}
        title={`Interview Evaluation: ${selectedInterview?.interview_type}`}
      >
        <form onSubmit={handleEvalSubmit} className="space-y-4">
          <div className="grid grid-cols-3 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Technical (1-10)</label>
              <input
                type="number"
                min="1"
                max="10"
                value={evalForm.technical_score}
                onChange={e => setEvalForm({ ...evalForm, technical_score: parseInt(e.target.value) })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Communication</label>
              <input
                type="number"
                min="1"
                max="10"
                value={evalForm.communication_score}
                onChange={e => setEvalForm({ ...evalForm, communication_score: parseInt(e.target.value) })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Overall</label>
              <input
                type="number"
                min="1"
                max="10"
                value={evalForm.overall_score}
                onChange={e => setEvalForm({ ...evalForm, overall_score: parseInt(e.target.value) })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Recommendation</label>
            <select
              value={evalForm.recommendation}
              onChange={e => setEvalForm({ ...evalForm, recommendation: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              <option value="Hire">Hire (Clear Round)</option>
              <option value="Strong Hire">Strong Hire</option>
              <option value="Reject">Reject (Do Not Proceed)</option>
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Evaluation Feedback</label>
            <textarea
              rows="3"
              value={evalForm.feedback}
              onChange={e => setEvalForm({ ...evalForm, feedback: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setEvalModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Submit Evaluation
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
