import React, { useEffect, useState } from 'react'
import leaveService from '../../services/erpnext/leave'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus } from 'lucide-react'

export default function LeaveAllocations() {
  const [allocations, setAllocations] = useState([])
  const [employees, setEmployees] = useState([])
  const [leaveTypes, setLeaveTypes] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    employee: '',
    leave_type: 'Casual Leave',
    from_date: '2026-01-01',
    to_date: '2026-12-31',
    new_leaves_allocated: 12,
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [aList, empList, ltList] = await Promise.all([
        leaveService.getLeaveAllocations(),
        employeeService.getEmployees(),
        leaveService.getLeaveTypes(),
      ])
      setAllocations(aList || [])
      setEmployees(empList || [])
      setLeaveTypes(ltList || [])
      if (empList && empList.length > 0 && !formData.employee) {
        setFormData(prev => ({ ...prev, employee: empList[0].name }))
      }
    } catch (err) {
      console.error('Failed to load leave allocations:', err)
      toast.error('Failed to load leave allocations from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await leaveService.createLeaveAllocation(formData)
      toast.success('Leave Allocation saved in ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Allocation failed')
    }
  }

  const columns = [
    { header: 'Allocation ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600' },
    { header: 'Employee', accessor: 'employee_name', className: 'font-semibold' },
    { header: 'Leave Type', accessor: 'leave_type' },
    { header: 'Period', render: row => `${row.from_date} to ${row.to_date}` },
    { header: 'Days Allocated', accessor: 'total_leaves_allocated', className: 'font-bold text-slate-800' },
    { header: 'Status', render: row => <StatusBadge status={row.docstatus === 1 ? 'Submitted' : 'Draft'} /> },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Leave Allocations</h1>
          <p className="text-xs text-slate-500 mt-1">Annual leave balances allocated in ERPNext</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Allocate Leave
        </button>
      </div>

      <DataTable
        columns={columns}
        data={allocations}
        searchField="employee_name"
        searchPlaceholder="Search allocations..."
        emptyMessage="No leave allocations found."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="Allocate Leaves">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Employee</label>
            <select
              value={formData.employee}
              onChange={e => setFormData({ ...formData, employee: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {employees.map(emp => (
                <option key={emp.name} value={emp.name}>{emp.employee_name} ({emp.name})</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Leave Type</label>
            <select
              value={formData.leave_type}
              onChange={e => setFormData({ ...formData, leave_type: e.target.value })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            >
              {leaveTypes.map(lt => (
                <option key={lt.name} value={lt.name}>{lt.name}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">From Date</label>
              <input
                type="date"
                required
                value={formData.from_date}
                onChange={e => setFormData({ ...formData, from_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">To Date</label>
              <input
                type="date"
                required
                value={formData.to_date}
                onChange={e => setFormData({ ...formData, to_date: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Allocated Days</label>
            <input
              type="number"
              min="1"
              required
              value={formData.new_leaves_allocated}
              onChange={e => setFormData({ ...formData, new_leaves_allocated: parseFloat(e.target.value) })}
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
            />
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Save Allocation
            </button>
          </div>
        </form>
      </Modal>
    </div>
  )
}
