import React, { useEffect, useState } from 'react'
import applicantService from '../../services/erpnext/applicants'
import jobOpeningService from '../../services/erpnext/jobOpenings'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { Plus } from 'lucide-react'

export default function Applicants() {
  const [applicants, setApplicants] = useState([])
  const [openings, setOpenings] = useState([])
  const [loading, setLoading] = useState(true)
  const [modalOpen, setModalOpen] = useState(false)
  const [formData, setFormData] = useState({
    applicant_name: '',
    email_id: '',
    phone_number: '',
    job_title: '',
    status: 'Open',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [data, openingsList] = await Promise.all([
        applicantService.getApplicants(),
        jobOpeningService.getJobOpenings().catch(() => [])
      ])
      setApplicants(data || [])
      setOpenings(openingsList || [])
    } catch (e) {
      console.error('Failed to load Applicants:', e)
      toast.error('Failed to load applicants from ERPNext')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    try {
      await applicantService.createApplicant(formData)
      toast.success('Applicant record created in ERPNext')
      setModalOpen(false)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to add Applicant')
    }
  }

  const [editModalOpen, setEditModalOpen] = useState(false)
  const [editFormData, setEditFormData] = useState(null)

  const handleEditSubmit = async (e) => {
    e.preventDefault()
    if (!editFormData) return
    try {
      await applicantService.updateApplicant(editFormData.name, {
        applicant_name: editFormData.applicant_name,
        email_id: editFormData.email_id,
        phone_number: editFormData.phone_number,
        job_title: editFormData.job_title,
        status: editFormData.status,
      })
      toast.success('Applicant updated in ERPNext')
      setEditModalOpen(false)
      setEditFormData(null)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to update Applicant')
    }
  }

  const columns = [
    { header: 'Applicant Name', accessor: 'applicant_name', className: 'font-semibold' },
    { header: 'Email ID', accessor: 'email_id' },
    { header: 'Phone', accessor: 'phone_number' },
    { header: 'Applied For', accessor: 'job_title' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: row => (
        <button
          onClick={() => {
            setEditFormData({ ...row })
            setEditModalOpen(true)
          }}
          className="px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
        >
          Edit
        </button>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Job Applicants</h1>
          <p className="text-xs text-slate-500 mt-1">Candidates in ERPNext Job Applicant registry</p>
        </div>
        <button
          onClick={() => setModalOpen(true)}
          className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" /> Add Applicant
        </button>
      </div>

      <DataTable
        columns={columns}
        data={applicants}
        searchField="applicant_name"
        searchPlaceholder="Search candidates..."
        emptyMessage="No applicants found."
        loading={loading}
      />

      <Modal isOpen={modalOpen} onClose={() => setModalOpen(false)} title="New Job Applicant">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Full Name</label>
            <input
              type="text"
              required
              value={formData.applicant_name}
              onChange={e => setFormData({ ...formData, applicant_name: e.target.value })}
              placeholder="Candidate Full Name"
              className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Email</label>
              <input
                type="email"
                required
                value={formData.email_id}
                onChange={e => setFormData({ ...formData, email_id: e.target.value })}
                placeholder="candidate@example.com"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Phone Number</label>
              <input
                type="text"
                value={formData.phone_number}
                onChange={e => setFormData({ ...formData, phone_number: e.target.value })}
                placeholder="+91 9876543210"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Position / Job Opening</label>
            {openings.length > 0 ? (
              <select
                value={formData.job_title}
                onChange={e => setFormData({ ...formData, job_title: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none bg-white"
              >
                <option value="">Select Job Opening...</option>
                {openings.map(o => (
                  <option key={o.name} value={o.name}>
                    {o.job_title} ({o.name})
                  </option>
                ))}
              </select>
            ) : (
              <input
                type="text"
                value={formData.job_title}
                onChange={e => setFormData({ ...formData, job_title: e.target.value })}
                placeholder="e.g. HR-OPN-2026-0001"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 outline-none"
              />
            )}
          </div>
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Save Applicant
            </button>
          </div>
        </form>
      </Modal>

      {/* Edit Applicant Modal */}
      <Modal isOpen={editModalOpen} onClose={() => setEditModalOpen(false)} title={`Edit Applicant: ${editFormData?.name}`}>
        {editFormData && (
          <form onSubmit={handleEditSubmit} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Candidate Name</label>
              <input
                type="text"
                required
                value={editFormData.applicant_name || ''}
                onChange={e => setEditFormData({ ...editFormData, applicant_name: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Email</label>
                <input
                  type="email"
                  required
                  value={editFormData.email_id || ''}
                  onChange={e => setEditFormData({ ...editFormData, email_id: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Phone</label>
                <input
                  type="text"
                  value={editFormData.phone_number || ''}
                  onChange={e => setEditFormData({ ...editFormData, phone_number: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Pipeline Status</label>
              <select
                value={editFormData.status || 'Open'}
                onChange={e => setEditFormData({ ...editFormData, status: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
              >
                <option value="Open">Open</option>
                <option value="Application Received">Application Received</option>
                <option value="Screening">Screening</option>
                <option value="Shortlisted">Shortlisted</option>
                <option value="Interview Round 1">Interview Round 1</option>
                <option value="Round 1 Passed">Round 1 Passed</option>
                <option value="Interview Round 2">Interview Round 2</option>
                <option value="Round 2 Passed">Round 2 Passed</option>
                <option value="Final Selection">Final Selection</option>
                <option value="Offer">Offer</option>
                <option value="Offer Accepted">Offer Accepted</option>
                <option value="Joining">Joining</option>
                <option value="Employee Created">Employee Created</option>
                <option value="Rejected">Rejected</option>
                <option value="Hold">Hold</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Position / Job Opening</label>
              {openings.length > 0 ? (
                <select
                  value={editFormData.job_title || ''}
                  onChange={e => setEditFormData({ ...editFormData, job_title: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
                >
                  <option value="">Select Job Opening...</option>
                  {openings.map(o => (
                    <option key={o.name} value={o.name}>
                      {o.job_title} ({o.name})
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  type="text"
                  value={editFormData.job_title || ''}
                  onChange={e => setEditFormData({ ...editFormData, job_title: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              )}
            </div>
            <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
              <button
                type="button"
                onClick={() => setEditModalOpen(false)}
                className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
              >
                Update in ERPNext
              </button>
            </div>
          </form>
        )}
      </Modal>
    </div>
  )
}
