import React, { useEffect, useState } from 'react'
import { Bell, CheckCircle2, Clock, Video, FileText, Check } from 'lucide-react'
import candidateService from '../../services/erpnext/candidate'

export default function CandidateNotifications() {
  const [applications, setApplications] = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState('all')

  const loadData = async () => {
    setLoading(true)
    try {
      const data = await candidateService.getMyApplications()
      setApplications(data || [])
    } catch (err) {
      console.error('Failed to load notifications:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  // Aggregate all notifications from all candidate applications
  const allNotifications = applications.flatMap((app) =>
    (app.notifications || []).map((n) => ({
      ...n,
      appName: app.name,
      jobName: app.job_name,
    }))
  )

  const filtered = allNotifications.filter((n) => {
    if (filter === 'unread') return !n.is_read
    return true
  })

  const handleMarkRead = async (appName, idx) => {
    try {
      await candidateService.markNotificationRead(appName, idx)
      loadData()
    } catch (err) {
      console.error(err)
    }
  }

  const getIcon = (type) => {
    switch (type) {
      case 'Interview':
        return <Video className="w-4 h-4 text-sky-600" />
      case 'Result':
        return <CheckCircle2 className="w-4 h-4 text-emerald-600" />
      default:
        return <FileText className="w-4 h-4 text-indigo-600" />
    }
  }

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Candidate Notifications</h1>
          <p className="text-xs text-slate-500 mt-1">
            Real-time updates regarding application submissions, interview schedules, and evaluation decisions.
          </p>
        </div>

        <div className="flex items-center gap-1 bg-white p-1 rounded-xl border border-slate-200 self-start sm:self-auto">
          <button
            onClick={() => setFilter('all')}
            className={`px-3 py-1 rounded-lg text-xs font-semibold transition-colors ${
              filter === 'all' ? 'bg-sky-600 text-white shadow-2xs' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            All ({allNotifications.length})
          </button>
          <button
            onClick={() => setFilter('unread')}
            className={`px-3 py-1 rounded-lg text-xs font-semibold transition-colors ${
              filter === 'unread' ? 'bg-sky-600 text-white shadow-2xs' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            Unread ({allNotifications.filter((n) => !n.is_read).length})
          </button>
        </div>
      </div>

      {loading ? (
        <div className="text-center py-20 text-slate-400 text-xs">
          <div className="w-8 h-8 border-2 border-sky-500 border-r-transparent rounded-full animate-spin mx-auto mb-3" />
          <span>Loading notifications...</span>
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-2xl border border-dashed border-slate-200 p-8">
          <Bell className="w-10 h-10 text-slate-300 mx-auto mb-3" />
          <h3 className="text-sm font-bold text-slate-700">No notifications found</h3>
          <p className="text-xs text-slate-400 mt-1">You're completely caught up with your candidate updates.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filtered.map((item, idx) => (
            <div
              key={idx}
              className={`p-4 rounded-2xl border transition-all flex items-start justify-between gap-4 ${
                item.is_read
                  ? 'bg-white border-slate-200'
                  : 'bg-sky-50/50 border-sky-200 shadow-2xs'
              }`}
            >
              <div className="flex items-start gap-3">
                <div
                  className={`p-2.5 rounded-xl border mt-0.5 shrink-0 ${
                    item.is_read
                      ? 'bg-slate-50 border-slate-200'
                      : 'bg-white border-sky-200 shadow-2xs'
                  }`}
                >
                  {getIcon(item.notification_type)}
                </div>
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-sm text-slate-800">{item.title}</span>
                    <span className="text-[10px] font-mono text-slate-400">
                      {item.jobName} ({item.appName})
                    </span>
                  </div>
                  <p className="text-xs text-slate-600 leading-relaxed">{item.message}</p>
                  <div className="text-[10px] text-slate-400 font-mono pt-1">
                    {item.date ? item.date.slice(0, 16) : 'Recent'}
                  </div>
                </div>
              </div>

              {!item.is_read && (
                <button
                  onClick={() => handleMarkRead(item.appName, item.idx)}
                  className="px-2.5 py-1 rounded-lg bg-white border border-sky-200 text-sky-700 hover:bg-sky-100 text-[11px] font-semibold flex items-center gap-1 shrink-0 transition-colors shadow-2xs"
                >
                  <Check className="w-3 h-3" />
                  <span>Mark Read</span>
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

