import api from './client'

export const payrollService = {
	async getPayrollEntries(filters = {}, limit = 50) {
		const params = {
			fields: JSON.stringify([
				'name',
				'company',
				'payroll_frequency',
				'start_date',
				'end_date',
				'status',
				'number_of_employees',
				'docstatus',
				'creation',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'creation desc',
		}
		const res = await api.get('/api/resource/Payroll Entry', params)
		return res.data || []
	},

	async getPayrollEntry(name) {
		const res = await api.get(`/api/resource/Payroll Entry/${encodeURIComponent(name)}`)
		return res.data
	},

	async createPayrollEntry(data) {
		const res = await api.post('/api/resource/Payroll Entry', data)
		return res.data
	},

	async generatePayrollAndSlips({
		company = 'Faircode',
		start_date,
		end_date,
		payroll_frequency = 'Monthly',
		employee = null,
	}) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.generate_payroll_and_slips', {
			company,
			start_date,
			end_date,
			payroll_frequency,
			employee,
		})
		return res.message
	},

	async getSalarySlips(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'company',
				'department',
				'designation',
				'start_date',
				'end_date',
				'posting_date',
				'gross_pay',
				'total_deduction',
				'net_pay',
				'status',
				'docstatus',
				'total_working_days',
				'payment_days',
				'custom_overtime_hours',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'posting_date desc, creation desc',
		}
		const res = await api.get('/api/resource/Salary Slip', params)
		return res.data || []
	},

	async getSalarySlip(name) {
		const res = await api.get(`/api/resource/Salary Slip/${encodeURIComponent(name)}`)
		return res.data
	},

	async submitSalarySlip(name) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.submit_salary_slip', {
			name,
		})
		return res.message || res.data
	},

	async submitAllDraftSalarySlips(company = 'Faircode', payroll_entry = null) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.submit_all_draft_salary_slips', {
			company,
			payroll_entry,
		})
		return res.message || res.data
	},
}

export default payrollService

