import api from './client'

export const applicantService = {
	async getApplicants(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'applicant_name',
				'email_id',
				'phone_number',
				'job_title',
				'designation',
				'status',
				'resume_attachment',
				'date_of_birth',
				'gender',
				'city',
				'state',
				'country',
				'highest_qualification',
				'institution',
				'graduation_year',
				'percentage_cgpa',
				'total_experience',
				'previous_company',
				'previous_designation',
				'previous_salary',
				'creation',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'creation desc',
		}
		const res = await api.get('/api/resource/Job Applicant', params)
		return res.data || []
	},

	async getApplicant(name) {
		const res = await api.get(`/api/resource/Job Applicant/${encodeURIComponent(name)}`)
		return res.data
	},

	async createApplicant(data) {
		const res = await api.post('/api/resource/Job Applicant', data)
		return res.data
	},

	async updateApplicant(name, data) {
		const res = await api.put(`/api/resource/Job Applicant/${encodeURIComponent(name)}`, data)
		return res.data
	},

	async updateApplicantStatus(name, status) {
		return this.updateApplicant(name, { status })
	},

	async screenApplicant(applicant, status = 'Shortlisted', notes = '') {
		const res = await api.post('/api/method/hrms.api.shift_checkout.screen_applicant', {
			applicant,
			status,
			notes,
		})
		return res.message || res.data
	},

	async getJobOffers(filters = {}, limit = 50) {
		const params = {
			fields: JSON.stringify([
				'name',
				'applicant_name',
				'applicant_email',
				'job_applicant',
				'offer_date',
				'designation',
				'company',
				'status',
				'docstatus',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'creation desc',
		}
		const res = await api.get('/api/resource/Job Offer', params)
		return res.data || []
	},

	async createJobOffer({ applicant, designation, department = 'Information Technology', company = 'Faircode', offer_date, salary = 40000 }) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.create_job_offer', {
			applicant,
			designation,
			department,
			company,
			offer_date: offer_date || new Date().toISOString().split('T')[0],
			salary,
		})
		return res.message || res.data
	},

	async uploadResume(file, docname = null) {
		const formData = new FormData()
		formData.append('file', file)
		formData.append('is_private', '0')
		if (docname) {
			formData.append('doctype', 'Job Applicant')
			formData.append('docname', docname)
		}
		const res = await api.post('/api/method/upload_file', formData)
		return res.message?.file_url || res.data?.file_url
	},
}

export default applicantService

