import React, { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../components/common/Toast'
import candidateService from '../services/erpnext/candidate'
import {
  User,
  Lock,
  Mail,
  Phone,
  UserPlus,
  ArrowLeft,
  CheckCircle2,
  AlertCircle,
} from 'lucide-react'

export default function Signup() {
  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    username: '',
    email: '',
    phone: '',
    password: '',
    confirm_password: '',
  })
  const [errors, setErrors] = useState({})
  const [loading, setLoading] = useState(false)
  const { login } = useAuth()
  const toast = useToast()
  const navigate = useNavigate()

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
    // Clear inline error when candidate modifies field
    if (errors[name]) {
      setErrors((prev) => {
        const next = { ...prev }
        delete next[name]
        return next
      })
    }
  }

  const validateForm = () => {
    const errs = {}

    // First Name
    if (!formData.first_name.trim()) {
      errs.first_name = 'First Name is required.'
    }

    // Last Name
    if (!formData.last_name.trim()) {
      errs.last_name = 'Last Name is required.'
    }

    // Contact Number
    if (!formData.phone.trim()) {
      errs.phone = 'Contact Number is required.'
    } else {
      const cleanPhone = formData.phone.replace(/\D/g, '')
      if (cleanPhone.length < 10) {
        errs.phone = 'Please enter a valid contact number (at least 10 digits).'
      }
    }

    // Email Address
    if (!formData.email.trim()) {
      errs.email = 'Email Address is required.'
    } else {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
      if (!emailRegex.test(formData.email.trim())) {
        errs.email = 'Please enter a valid email address.'
      }
    }

    // Password
    if (!formData.password) {
      errs.password = 'Password is required.'
    } else if (formData.password.length < 6) {
      errs.password = 'Password must be at least 6 characters long.'
    }

    // Confirm Password
    if (!formData.confirm_password) {
      errs.confirm_password = 'Confirm Password is required.'
    } else if (formData.password !== formData.confirm_password) {
      errs.confirm_password = 'Passwords do not match.'
    }

    return errs
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    const validationErrors = validateForm()
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors)
      const firstError = Object.values(validationErrors)[0]
      toast.error(firstError)
      return
    }

    try {
      setLoading(true)
      const fullName = `${formData.first_name.trim()} ${formData.last_name.trim()}`
      
      await candidateService.registerCandidate({
        firstName: formData.first_name.trim(),
        lastName: formData.last_name.trim(),
        username: formData.username.trim() || undefined,
        fullName,
        email: formData.email.trim(),
        password: formData.password,
        confirmPassword: formData.confirm_password,
        phone: formData.phone.trim(),
      })

      toast.success(`Welcome ${fullName}! Your candidate account is ready.`)

      try {
        await login(formData.email.trim(), formData.password)
        navigate('/candidate/dashboard')
      } catch (loginErr) {
        console.warn('Auto-login notice:', loginErr)
        navigate('/login')
      }
    } catch (err) {
      console.error('Registration error:', err)
      const userMsg = err.userMessage || 'Registration failed. Email may already be registered.'
      
      if (
        userMsg.toLowerCase().includes('already exists') ||
        userMsg.toLowerCase().includes('already registered') ||
        userMsg.toLowerCase().includes('email')
      ) {
        const duplicateMsg = 'An account with this email already exists. Please sign in.'
        setErrors((prev) => ({ ...prev, email: duplicateMsg }))
        toast.error(duplicateMsg)
      } else {
        toast.error(userMsg)
      }
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-indigo-950 to-slate-900 flex items-center justify-center p-4 sm:p-6">
      <div className="bg-white/95 backdrop-blur-md rounded-2xl border border-white/20 w-full max-w-lg p-6 sm:p-8 shadow-2xl">
        <div className="text-center mb-6">
          <div className="w-12 h-12 rounded-xl bg-indigo-600 flex items-center justify-center text-white font-black text-2xl mx-auto mb-3 shadow-lg shadow-indigo-500/30">
            F
          </div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Sign Up as Candidate</h1>
          <p className="text-xs text-slate-500 mt-1 font-medium">
            Join Faircode to explore career opportunities and apply for open positions
          </p>
        </div>

        <form onSubmit={handleSubmit} noValidate className="space-y-4">
          {/* First & Last Name */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
                First Name *
              </label>
              <div className="relative">
                <User className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  name="first_name"
                  autoComplete="given-name"
                  value={formData.first_name}
                  onChange={handleChange}
                  placeholder="e.g. Aarav"
                  className={`w-full pl-9 pr-3 py-2 text-sm rounded-xl border focus:outline-none transition-colors ${
                    errors.first_name
                      ? 'border-rose-400 focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 bg-rose-50/30'
                      : 'border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50'
                  }`}
                />
              </div>
              {errors.first_name && (
                <p className="text-xs text-rose-600 font-medium mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                  <span>{errors.first_name}</span>
                </p>
              )}
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
                Last Name *
              </label>
              <input
                type="text"
                name="last_name"
                autoComplete="family-name"
                value={formData.last_name}
                onChange={handleChange}
                placeholder="e.g. Sharma"
                className={`w-full px-3 py-2 text-sm rounded-xl border focus:outline-none transition-colors ${
                  errors.last_name
                    ? 'border-rose-400 focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 bg-rose-50/30'
                    : 'border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50'
                }`}
              />
              {errors.last_name && (
                <p className="text-xs text-rose-600 font-medium mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                  <span>{errors.last_name}</span>
                </p>
              )}
            </div>
          </div>

          {/* Username & Contact Number */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
                Username
              </label>
              <div className="relative">
                <User className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  name="username"
                  autoComplete="off"
                  value={formData.username}
                  onChange={handleChange}
                  placeholder="e.g. aaravsharma"
                  className="w-full pl-9 pr-3 py-2 text-sm rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
                Contact Number *
              </label>
              <div className="relative">
                <Phone className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="tel"
                  name="phone"
                  autoComplete="tel"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="e.g. 9876543210"
                  className={`w-full pl-9 pr-3 py-2 text-sm rounded-xl border focus:outline-none transition-colors ${
                    errors.phone
                      ? 'border-rose-400 focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 bg-rose-50/30'
                      : 'border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50'
                  }`}
                />
              </div>
              {errors.phone && (
                <p className="text-xs text-rose-600 font-medium mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                  <span>{errors.phone}</span>
                </p>
              )}
            </div>
          </div>

          {/* Email Address */}
          <div>
            <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
              Email Address *
            </label>
            <div className="relative">
              <Mail className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="email"
                name="email"
                autoComplete="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="candidate@faircode.com"
                className={`w-full pl-9 pr-3 py-2 text-sm rounded-xl border focus:outline-none transition-colors ${
                  errors.email
                    ? 'border-rose-400 focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 bg-rose-50/30'
                    : 'border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50'
                }`}
              />
            </div>
            {errors.email && (
              <p className="text-xs text-rose-600 font-medium mt-1 flex items-center gap-1">
                <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                <span>{errors.email}</span>
              </p>
            )}
          </div>

          {/* Password & Confirm Password */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
                Password *
              </label>
              <div className="relative">
                <Lock className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="password"
                  name="password"
                  autoComplete="new-password"
                  value={formData.password}
                  onChange={handleChange}
                  placeholder="••••••••"
                  className={`w-full pl-9 pr-3 py-2 text-sm rounded-xl border focus:outline-none transition-colors ${
                    errors.password
                      ? 'border-rose-400 focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 bg-rose-50/30'
                      : 'border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50'
                  }`}
                />
              </div>
              {errors.password && (
                <p className="text-xs text-rose-600 font-medium mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                  <span>{errors.password}</span>
                </p>
              )}
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1">
                Confirm Password *
              </label>
              <div className="relative">
                <Lock className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="password"
                  name="confirm_password"
                  autoComplete="new-password"
                  value={formData.confirm_password}
                  onChange={handleChange}
                  placeholder="••••••••"
                  className={`w-full pl-9 pr-3 py-2 text-sm rounded-xl border focus:outline-none transition-colors ${
                    errors.confirm_password
                      ? 'border-rose-400 focus:border-rose-500 focus:ring-2 focus:ring-rose-500/20 bg-rose-50/30'
                      : 'border-slate-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 bg-slate-50/50'
                  }`}
                />
              </div>
              {errors.confirm_password && (
                <p className="text-xs text-rose-600 font-medium mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                  <span>{errors.confirm_password}</span>
                </p>
              )}
            </div>
          </div>

          <div className="p-3.5 bg-indigo-50/80 rounded-xl border border-indigo-200/70 flex items-start gap-2.5 text-xs text-indigo-900">
            <CheckCircle2 className="w-4 h-4 text-indigo-600 flex-shrink-0 mt-0.5" />
            <div>
              <span className="font-semibold">Candidate Portal Access:</span> Your account provides exclusive access to browse open positions, submit job applications, track evaluation status, and attend video interviews.
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 px-4 rounded-xl text-white font-semibold text-sm shadow-md disabled:opacity-50 transition-all flex items-center justify-center gap-2 mt-4 bg-indigo-600 hover:bg-indigo-700 shadow-indigo-600/20 cursor-pointer"
          >
            {loading ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-r-transparent rounded-full animate-spin" />
                <span>Registering as Candidate &amp; Signing In...</span>
              </>
            ) : (
              <>
                <UserPlus className="w-4 h-4" />
                <span>Register as Candidate &amp; Sign In</span>
              </>
            )}
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-slate-100 flex items-center justify-between text-xs">
          <Link
            to="/login"
            className="flex items-center gap-1.5 text-indigo-600 hover:text-indigo-800 font-semibold transition-colors"
          >
            <ArrowLeft className="w-3.5 h-3.5" />
            <span>Already have an account? Sign In</span>
          </Link>
          <span className="text-slate-400">Faircode</span>
        </div>
      </div>
    </div>
  )
}
