import api from './client'

export const overtimeService = {
	async getOvertimeRecords(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'date',
				'ot_hours',
				'current_salary',
				'working_days',
				'overtime_rate',
				'overtime_amount',
				'creation',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'date desc',
		}
		try {
			const res = await api.get('/api/resource/Employee Overtime Log', params)
			return res.data || []
		} catch {
			return []
		}
	},

	async recordOvertime({ employee, date, ot_hours, current_salary, working_days = 26, overtime_rate = 1.75, attendance = null, shift = null, remarks = null }) {
		const res = await api.post('/api/method/hrms.api.shift_checkout.record_overtime', {
			employee,
			date,
			ot_hours,
			current_salary,
			working_days,
			overtime_rate,
			attendance,
			shift,
			remarks,
		})
		return res.message || res.data
	},
}

export default overtimeService

