import api from './client'

export const shiftService = {
	async getShiftTypes() {
		const res = await api.get('/api/resource/Shift Type', {
			fields: JSON.stringify(['name', 'start_time', 'end_time', 'enable_auto_attendance']),
			limit_page_length: 50,
		})
		return (res.data || []).map(st => {
			let totalHours = 8
			if (st.name && st.name.includes('36')) {
				totalHours = 36
			}
			return {
				...st,
				total_hours: totalHours,
			}
		})
	},

	async createShiftType({ name, start_time = '09:00:00', end_time = '21:00:00' }) {
		const res = await api.post('/api/resource/Shift Type', {
			name,
			start_time,
			end_time,
			enable_auto_attendance: 1,
		})
		return res.data
	},

	async getShiftAssignments(filters = {}, limit = 100) {
		const params = {
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'shift_type',
				'start_date',
				'end_date',
				'status',
				'docstatus',
			]),
			filters: JSON.stringify(filters),
			limit_page_length: limit,
			order_by: 'start_date desc',
		}
		const res = await api.get('/api/resource/Shift Assignment', params)
		return res.data || []
	},

	async createShiftAssignment({ employee, shift_type, start_date, end_date = null, company = 'Faircode' }) {
		const res = await api.post('/api/resource/Shift Assignment', {
			employee,
			shift_type,
			start_date,
			end_date,
			company,
			status: 'Active',
			docstatus: 1, // submitted
		})
		return res.data
	},

	async getEmployeeShiftStatus(employee) {
		if (!employee) return null
		const res = await api.get('/api/method/hrms.api.shift_checkout.get_employee_shift_status', {
			employee,
		})
		return res.message
	},
}

export default shiftService

