import React, { useEffect, useState } from 'react'
import { useParams, Link } from 'react-router-dom'
import payrollService from '../../services/erpnext/payroll'
import StatusBadge from '../../components/common/StatusBadge'
import { ArrowLeft, Printer, Building2, CheckCircle2 } from 'lucide-react'
import { useToast } from '../../components/common/Toast'

export default function SalarySlipDetail() {
  const { id } = useParams()
  const [slip, setSlip] = useState(null)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const toast = useToast()

  const loadSlip = () => {
    if (id) {
      setLoading(true)
      payrollService.getSalarySlip(id).then(data => {
        setSlip(data)
        setLoading(false)
      }).catch(err => {
        console.error('Failed to load slip:', err)
        setLoading(false)
      })
    }
  }

  useEffect(() => {
    loadSlip()
  }, [id])

  const handleSubmit = async () => {
    if (!slip) return
    setSubmitting(true)
    try {
      await payrollService.submitSalarySlip(slip.name)
      toast.success(`Salary Slip ${slip.name} submitted successfully in ERPNext!`)
      loadSlip()
    } catch (err) {
      toast.error(err.userMessage || `Failed to submit Salary Slip ${slip.name}`)
    } finally {
      setSubmitting(false)
    }
  }

  if (loading) {
    return (
      <div className="py-20 text-center text-slate-400">
        <div className="inline-block animate-spin rounded-full h-8 w-8 border-2 border-indigo-600 border-r-transparent mr-2 align-middle"></div>
        Loading salary slip from ERPNext...
      </div>
    )
  }

  if (!slip) {
    return (
      <div className="py-20 text-center text-slate-500">
        Salary Slip not found on server
      </div>
    )
  }

  const isDraft = slip.docstatus === 0 || slip.status === 'Draft'

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <Link to="/salary-slips" className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-800">
          <ArrowLeft className="w-4 h-4" /> Back to Salary Slips
        </Link>
        <div className="flex items-center gap-2">
          {isDraft && (
            <button
              onClick={handleSubmit}
              disabled={submitting}
              className="px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold flex items-center gap-1.5 shadow-sm disabled:opacity-50 transition-all"
            >
              <CheckCircle2 className="w-3.5 h-3.5" />
              <span>{submitting ? 'Submitting...' : 'Submit Salary Slip'}</span>
            </button>
          )}
          <button
            onClick={() => window.print()}
            className="px-3 py-1.5 rounded-lg border border-slate-200 text-xs font-medium text-slate-600 hover:bg-slate-50 flex items-center gap-1.5 shadow-sm"
          >
            <Printer className="w-3.5 h-3.5" /> Print Slip
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 p-8 shadow-sm space-y-6">
        {/* Header */}
        <div className="border-b border-slate-100 pb-6 flex items-start justify-between">
          <div>
            <div className="flex items-center gap-2">
              <Building2 className="w-5 h-5 text-indigo-600" />
              <h2 className="text-xl font-bold text-slate-800">{slip.company}</h2>
            </div>
            <p className="text-xs text-slate-500 mt-1">Salary Slip for period: <span className="font-semibold text-slate-700">{slip.start_date} to {slip.end_date}</span></p>
          </div>
          <div className="text-right">
            <div className="text-xs font-mono text-slate-400">{slip.name}</div>
            <div className="mt-1"><StatusBadge status={slip.status} /></div>
          </div>
        </div>

        {/* Employee & Working Days Info */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100 text-xs">
          <div>
            <span className="text-slate-400 block mb-0.5">Employee Name</span>
            <span className="font-bold text-slate-800">{slip.employee_name}</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Employee ID</span>
            <span className="font-mono text-indigo-600 font-semibold">{slip.employee}</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Designation</span>
            <span className="font-semibold text-slate-700">{slip.designation}</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Department</span>
            <span className="font-semibold text-slate-700">{slip.department}</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Working Days</span>
            <span className="font-bold text-slate-800">{slip.total_working_days} Days</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Payment Days</span>
            <span className="font-bold text-slate-800">{slip.payment_days} Days</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Overtime Hours</span>
            <span className="font-bold text-indigo-600">{slip.custom_overtime_hours || 0} Hours</span>
          </div>
          <div>
            <span className="text-slate-400 block mb-0.5">Posting Date</span>
            <span className="font-medium text-slate-700">{slip.posting_date}</span>
          </div>
        </div>

        {/* Earnings & Deductions Tables */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Earnings */}
          <div className="border border-slate-200 rounded-xl overflow-hidden">
            <div className="bg-emerald-50/75 px-4 py-2.5 border-b border-emerald-100 font-bold text-xs text-emerald-900 uppercase tracking-wider">
              Earnings
            </div>
            <table className="w-full text-xs text-left">
              <tbody className="divide-y divide-slate-100">
                {(slip.earnings || []).map((e, idx) => (
                  <tr key={idx} className="hover:bg-slate-50">
                    <td className="px-4 py-2.5 font-medium text-slate-700">{e.salary_component}</td>
                    <td className="px-4 py-2.5 text-right font-semibold text-slate-800">₹{parseFloat(e.amount || 0).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-slate-50 font-bold border-t border-slate-200">
                  <td className="px-4 py-2.5 text-slate-800">Gross Pay</td>
                  <td className="px-4 py-2.5 text-right text-emerald-700 font-bold">₹{parseFloat(slip.gross_pay || 0).toLocaleString()}</td>
                </tr>
              </tfoot>
            </table>
          </div>

          {/* Deductions */}
          <div className="border border-slate-200 rounded-xl overflow-hidden">
            <div className="bg-rose-50/75 px-4 py-2.5 border-b border-rose-100 font-bold text-xs text-rose-900 uppercase tracking-wider">
              Deductions
            </div>
            <table className="w-full text-xs text-left">
              <tbody className="divide-y divide-slate-100">
                {(slip.deductions || []).map((d, idx) => (
                  <tr key={idx} className="hover:bg-slate-50">
                    <td className="px-4 py-2.5 font-medium text-slate-700">{d.salary_component}</td>
                    <td className="px-4 py-2.5 text-right font-semibold text-slate-800">₹{parseFloat(d.amount || 0).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-slate-50 font-bold border-t border-slate-200">
                  <td className="px-4 py-2.5 text-slate-800">Total Deductions</td>
                  <td className="px-4 py-2.5 text-right text-rose-700 font-bold">₹{parseFloat(slip.total_deduction || 0).toLocaleString()}</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        {/* Net Pay Banner */}
        <div className="bg-gradient-to-r from-emerald-500 to-teal-600 rounded-xl p-6 text-white flex flex-col sm:flex-row items-center justify-between gap-4 shadow-sm">
          <div>
            <div className="text-xs font-semibold uppercase tracking-wider text-emerald-100">Net Take-Home Salary</div>
            <div className="text-3xl font-black mt-1 tracking-tight">₹{parseFloat(slip.net_pay || 0).toLocaleString()}</div>
          </div>
          <div className="text-xs text-emerald-100 text-right">
            <div>Calculated by ERPNext Salary Engine</div>
            <div className="font-mono text-[11px] text-emerald-200 mt-0.5">{slip.name}</div>
          </div>
        </div>
      </div>
    </div>
  )
}
