import React, { useEffect, useState } from 'react'
import {
  Clock,
  LogIn,
  LogOut,
  RefreshCw,
  CheckCircle2,
  AlertTriangle,
  Zap,
  ShieldCheck,
  Calendar,
} from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import attendanceService from '../../services/erpnext/attendance'
import shiftService from '../../services/erpnext/shifts'
import StatusBadge from '../../components/common/StatusBadge'
import { useToast } from '../../components/common/Toast'

export default function UserCheckin() {
  const { user, employee } = useAuth()
  const empId = employee?.name || ''
  const toast = useToast()

  const [shiftStatus, setShiftStatus] = useState(null)
  const [recentLogs, setRecentLogs] = useState([])
  const [loading, setLoading] = useState(false)
  const [actionLoading, setActionLoading] = useState(false)

  const loadData = async () => {
    if (!empId) return
    setLoading(true)
    try {
      const [status, logs] = await Promise.all([
        shiftService.getEmployeeShiftStatus(empId).catch(() => null),
        attendanceService.getCheckins({ employee: empId }, 20).catch(() => []),
      ])
      setShiftStatus(status)
      setRecentLogs(logs || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [empId])

  const handleCheckIn = async () => {
    try {
      setActionLoading(true)
      await attendanceService.checkIn(empId)
      toast.success(`Check-In recorded in ERPNext for ${employee?.employee_name || empId}`)
      await loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Check-in failed')
    } finally {
      setActionLoading(false)
    }
  }

  const handleCheckOut = async () => {
    try {
      setActionLoading(true)
      await attendanceService.checkOut(empId)
      toast.success(`Check-Out recorded in ERPNext for ${employee?.employee_name || empId}`)
      await loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Check-out failed')
    } finally {
      setActionLoading(false)
    }
  }

  const handleAutoCheckout = async () => {
    try {
      setActionLoading(true)
      const res = await attendanceService.processAutoCheckoutAndAttendance(empId, true)
      toast.success('Automatic 36H Checkout & Attendance processor executed!')
      await loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Auto-checkout processor failed')
    } finally {
      setActionLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Check-In / Check-Out</h1>
          <p className="text-xs text-slate-500 mt-1">
            Personal attendance recording terminal for {employee?.employee_name || user?.full_name || 'Employee'} {empId ? `(${empId})` : ''}
          </p>
        </div>
        <button
          onClick={loadData}
          disabled={loading || actionLoading}
          className="px-3.5 py-2 rounded-xl bg-white border border-slate-200 text-slate-700 text-xs font-semibold shadow-sm hover:bg-slate-50 transition-colors flex items-center gap-2 self-start sm:self-auto"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          <span>Refresh</span>
        </button>
      </div>

      {/* 36-Hour Continuous Shift Architecture Info Banner */}
      <div className="rounded-2xl border border-indigo-200 bg-indigo-50/50 p-5 sm:p-6">
        <div className="flex items-start gap-4">
          <div className="p-3 rounded-xl bg-indigo-600 text-white shrink-0 shadow-md shadow-indigo-600/20">
            <Clock className="w-6 h-6" />
          </div>
          <div className="space-y-1">
            <h3 className="text-sm font-bold text-indigo-950 flex items-center gap-2">
              <span>36-Hour Continuous Shift Active</span>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-100 text-indigo-700 border border-indigo-200">
                Idempotent Engine
              </span>
            </h3>
            <p className="text-xs text-indigo-800 leading-relaxed max-w-3xl">
              Your assigned shift duration is configured as <strong>36.0 hours</strong>. When you log an <strong>IN</strong> check-in, the system dynamically computes the multi-day checkout boundary: <code className="bg-white/80 px-1.5 py-0.5 rounded text-indigo-900 border border-indigo-200 font-mono text-[11px]">Shift End = Check-In + 36 Hours</code>. The automated server engine guarantees reconciliation into ERPNext Attendance records.
            </p>
          </div>
        </div>
      </div>

      {/* Main Terminal Controls & Shift Status */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Terminal Controls */}
        <div className="lg:col-span-1 bg-white rounded-2xl border border-slate-200 p-6 shadow-sm flex flex-col justify-between">
          <div>
            <h2 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 pb-3 border-b border-slate-100 flex items-center gap-2">
              <Zap className="w-4 h-4 text-indigo-600" />
              <span>Biometric Actions</span>
            </h2>

            <div className="space-y-3 mb-6">
              <div className="p-3.5 rounded-xl bg-slate-50 border border-slate-100 text-xs space-y-1.5">
                <div className="text-slate-400 font-medium">Logged In As</div>
                <div className="font-bold text-slate-800 text-sm">{employee?.employee_name || user?.full_name || 'Employee'}</div>
                <div className="font-mono text-indigo-600 text-[11px]">{empId}</div>
              </div>

              <div className="p-3.5 rounded-xl bg-slate-50 border border-slate-100 text-xs space-y-1.5">
                <div className="text-slate-400 font-medium">Shift Type</div>
                <div className="font-semibold text-slate-800">{shiftStatus?.shift || 'No Shift Assigned'}</div>
                <div className="text-[11px] text-slate-500">Configured Duration: {shiftStatus?.duration_hours ? `${shiftStatus.duration_hours}h` : '-'}</div>
              </div>
            </div>
          </div>

          <div className="space-y-3">
            <button
              onClick={handleCheckIn}
              disabled={actionLoading || shiftStatus?.is_checked_in}
              className="w-full py-3 px-4 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs shadow-md shadow-emerald-600/20 disabled:opacity-50 transition-all flex items-center justify-center gap-2"
            >
              <LogIn className="w-4 h-4" />
              <span>{shiftStatus?.is_checked_in ? 'Already Checked In' : 'Record Biometric Check-In (IN)'}</span>
            </button>

            <button
              onClick={handleCheckOut}
              disabled={actionLoading || !shiftStatus?.is_checked_in}
              className="w-full py-3 px-4 rounded-xl bg-rose-600 hover:bg-rose-500 text-white font-semibold text-xs shadow-md shadow-rose-600/20 disabled:opacity-50 transition-all flex items-center justify-center gap-2"
            >
              <LogOut className="w-4 h-4" />
              <span>Record Check-Out (OUT)</span>
            </button>

            <div className="pt-2 border-t border-slate-100">
              <button
                onClick={handleAutoCheckout}
                disabled={actionLoading}
                className="w-full py-2.5 px-3 rounded-xl bg-indigo-50 hover:bg-indigo-100 text-indigo-700 font-semibold text-xs border border-indigo-200 disabled:opacity-50 transition-all flex items-center justify-center gap-1.5"
              >
                <RefreshCw className={`w-3.5 h-3.5 ${actionLoading ? 'animate-spin' : ''}`} />
                <span>Trigger Server 36H Auto-Checkout</span>
              </button>
            </div>
          </div>
        </div>

        {/* Live Shift State & Check-In History */}
        <div className="lg:col-span-2 bg-white rounded-2xl border border-slate-200 p-6 shadow-sm flex flex-col justify-between">
          <div>
            <h2 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 pb-3 border-b border-slate-100 flex items-center justify-between">
              <span className="flex items-center gap-2">
                <Calendar className="w-4 h-4 text-indigo-600" />
                <span>Recent Check-In / Check-Out Logs</span>
              </span>
              <span className="text-xs font-normal text-slate-400">Total Logs: {recentLogs.length}</span>
            </h2>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-slate-100 text-slate-400 font-semibold uppercase tracking-wider">
                    <th className="pb-3">Type</th>
                    <th className="pb-3">Timestamp</th>
                    <th className="pb-3">Shift</th>
                    <th className="pb-3">Device / Origin</th>
                    <th className="pb-3">Document ID</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {recentLogs.length === 0 ? (
                    <tr>
                      <td colSpan="5" className="py-8 text-center text-slate-400">
                        No check-in logs found for this employee.
                      </td>
                    </tr>
                  ) : (
                    recentLogs.map((log, idx) => (
                      <tr key={idx} className="hover:bg-slate-50/60">
                        <td className="py-3">
                          <span
                            className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold ${
                              log.log_type === 'IN'
                                ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                                : 'bg-rose-50 text-rose-700 border border-rose-200'
                            }`}
                          >
                            {log.log_type === 'IN' ? <LogIn className="w-3 h-3" /> : <LogOut className="w-3 h-3" />}
                            {log.log_type}
                          </span>
                        </td>
                        <td className="py-3 font-mono text-slate-800 font-semibold">{log.time}</td>
                        <td className="py-3 text-slate-600">{log.shift || '-'}</td>
                        <td className="py-3 font-medium text-slate-500">{log.device_id || 'Terminal'}</td>
                        <td className="py-3 font-mono text-slate-400 text-[11px]">{log.name}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

