import React, { createContext, useContext, useState, useEffect } from 'react'
import authService from '../services/erpnext/auth'
import employeeService from '../services/erpnext/employees'

const AuthContext = createContext(null)

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  const checkAuth = async () => {
    try {
      const loggedUser = await authService.getLoggedUser()
      if (loggedUser && loggedUser !== 'Guest') {
        const userInfo = await authService.getCurrentUserInfo()
        const roles = (userInfo?.roles || []).map(r => (typeof r === 'string' ? r : r.role))

        const isAdmin = Boolean(
          userInfo?.is_admin ||
          roles.includes('Administrator') ||
          roles.includes('System Manager') ||
          roles.includes('HR Manager') ||
          loggedUser === 'Administrator' ||
          userInfo?.name === 'Administrator' ||
          userInfo?.username === 'administrator'
        )

        const hasEmployeeDoc = Boolean(userInfo?.employee || userInfo?.is_employee || userInfo?.account_type === 'employee')
        const isEmployee = Boolean(!isAdmin && (hasEmployeeDoc || roles.includes('Employee') || roles.includes('Employee Self Service')))
        const isCandidate = Boolean(!isAdmin && !isEmployee && (userInfo?.is_candidate || userInfo?.account_type === 'candidate' || roles.includes('Candidate')))
        const accountType = isAdmin ? 'admin' : (isEmployee ? 'employee' : (isCandidate ? 'candidate' : 'user'))

        let employee = isCandidate ? null : (userInfo?.employee || null)
        if (isEmployee && !employee) {
          try {
            const emps = await employeeService.getEmployees(
              { user_id: userInfo?.name || loggedUser },
              1
            )
            if (emps && emps.length > 0) {
              employee = await employeeService.getEmployee(emps[0].name)
            } else if (userInfo?.email) {
              const fallbackEmps = await employeeService.getEmployees(
                { personal_email: userInfo.email },
                1
              )
              if (fallbackEmps && fallbackEmps.length > 0) {
                employee = await employeeService.getEmployee(fallbackEmps[0].name)
              }
            }
          } catch {
            // Ignore employee fetch errors
          }
        }

        const fullUserData = {
          ...(userInfo || {}),
          name: userInfo?.name || loggedUser,
          email: userInfo?.email || loggedUser,
          full_name: userInfo?.full_name || loggedUser,
          username: userInfo?.username || loggedUser,
          roles,
          isAdmin,
          isCandidate,
          isEmployee,
          accountType,
          employee: isCandidate ? null : employee,
        }
        setUser(fullUserData)
        return fullUserData
      } else {
        setUser(null)
        return null
      }
    } catch {
      setUser(null)
      return null
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    checkAuth()
  }, [])

  const login = async (username, password) => {
    await authService.login(username.trim(), password)
    return await checkAuth()
  }

  const logout = async () => {
    try {
      await authService.logout()
    } catch {
      // ignore
    }
    setUser(null)
    window.location.href = '/login'
  }

  return (
    <AuthContext.Provider
      value={{
        user,
        isAdmin: user?.isAdmin ?? false,
        isEmployee: user?.isEmployee ?? false,
        isCandidate: user?.isCandidate ?? false,
        employee: user?.employee ?? null,
        loading,
        login,
        logout,
        checkAuth,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  return useContext(AuthContext)
}
