import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import employeeService from '../../services/erpnext/employees'
import DataTable from '../../components/common/DataTable'
import StatusBadge from '../../components/common/StatusBadge'
import Modal from '../../components/common/Modal'
import { useToast } from '../../components/common/Toast'
import { UserPlus, Eye, Plus, Edit2 } from 'lucide-react'

export default function EmployeeList() {
  const [employees, setEmployees] = useState([])
  const [departments, setDepartments] = useState([])
  const [loading, setLoading] = useState(true)
  const [createModalOpen, setCreateModalOpen] = useState(false)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [editFormData, setEditFormData] = useState(null)
  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    gender: 'Male',
    date_of_birth: '1995-05-15',
    date_of_joining: new Date().toISOString().split('T')[0],
    company: 'Faircode',
    department: 'Information Technology - F',
    designation: 'Software Developer',
    personal_email: '',
    company_email: '',
    employment_type: 'Full-time',
    status: 'Active',
  })
  const toast = useToast()

  const loadData = async () => {
    setLoading(true)
    try {
      const [empList, deptList] = await Promise.all([
        employeeService.getEmployees(),
        employeeService.getDepartments().catch(() => []),
      ])
      setEmployees(empList || [])
      setDepartments(deptList || [])
      if (deptList.length > 0 && !formData.department) {
        setFormData(prev => ({ ...prev, department: deptList[0].name }))
      }
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadData()
  }, [])

  const handleCreateSubmit = async (e) => {
    e.preventDefault()
    try {
      const payload = {
        first_name: formData.first_name,
        last_name: formData.last_name,
        employee_name: `${formData.first_name} ${formData.last_name}`.trim(),
        gender: formData.gender,
        date_of_birth: formData.date_of_birth,
        date_of_joining: formData.date_of_joining,
        company: formData.company,
        department: formData.department,
        designation: formData.designation,
        personal_email: formData.personal_email || `${formData.first_name.toLowerCase()}@example.com`,
        company_email: formData.company_email || `${formData.first_name.toLowerCase()}@faircode.com`,
        employment_type: formData.employment_type,
        status: 'Active',
      }
      const res = await employeeService.createEmployee(payload)
      toast.success(`Employee ${res.name || res.employee_name} created successfully in ERPNext!`)
      setCreateModalOpen(false)
      setFormData({
        first_name: '',
        last_name: '',
        gender: 'Male',
        date_of_birth: '1995-05-15',
        date_of_joining: new Date().toISOString().split('T')[0],
        company: 'Faircode',
        department: departments.length > 0 ? departments[0].name : 'Information Technology - F',
        designation: 'Software Developer',
        personal_email: '',
        company_email: '',
        employment_type: 'Full-time',
        status: 'Active',
      })
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to create employee')
    }
  }

  const handleEditSubmit = async (e) => {
    e.preventDefault()
    if (!editFormData) return
    try {
      await employeeService.updateEmployee(editFormData.name, {
        first_name: editFormData.first_name,
        last_name: editFormData.last_name,
        designation: editFormData.designation,
        department: editFormData.department,
        status: editFormData.status,
        employment_type: editFormData.employment_type,
        personal_email: editFormData.personal_email,
        company_email: editFormData.company_email,
      })
      toast.success(`Employee ${editFormData.name} updated in ERPNext`)
      setEditModalOpen(false)
      setEditFormData(null)
      loadData()
    } catch (err) {
      toast.error(err.userMessage || 'Failed to update employee')
    }
  }

  const columns = [
    { header: 'Employee ID', accessor: 'name', className: 'font-mono text-xs text-indigo-600 font-semibold' },
    { header: 'Employee Name', accessor: 'employee_name', className: 'font-semibold' },
    { header: 'Designation', accessor: 'designation' },
    { header: 'Department', accessor: 'department' },
    { header: 'Joining Date', accessor: 'date_of_joining' },
    { header: 'Status', render: row => <StatusBadge status={row.status} /> },
    {
      header: 'Actions',
      render: row => (
        <div className="flex items-center gap-1.5">
          <Link
            to={`/employees/${encodeURIComponent(row.name)}`}
            className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 rounded-lg hover:bg-indigo-100"
          >
            <Eye className="w-3.5 h-3.5" /> Profile
          </Link>
          <button
            onClick={() => {
              setEditFormData({ ...row })
              setEditModalOpen(true)
            }}
            className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium text-slate-600 bg-slate-50 border border-slate-200 rounded-lg hover:bg-slate-100"
          >
            <Edit2 className="w-3 h-3" /> Edit
          </button>
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Employee Directory</h1>
          <p className="text-xs text-slate-500 mt-1">Live Employee records from ERPNext database</p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setCreateModalOpen(true)}
            className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 shadow-sm flex items-center gap-1.5"
          >
            <Plus className="w-4 h-4" /> Add Employee
          </button>
          <Link
            to="/onboarding"
            className="px-3.5 py-2 rounded-lg bg-slate-100 text-slate-700 border border-slate-200 text-xs font-semibold hover:bg-slate-200 flex items-center gap-1.5"
          >
            <UserPlus className="w-4 h-4" /> Onboard from Offer
          </Link>
        </div>
      </div>

      <DataTable
        columns={columns}
        data={employees}
        searchField="employee_name"
        searchPlaceholder="Search employees by name..."
        emptyMessage="No employees found."
        loading={loading}
      />

      {/* Create Employee Modal */}
      <Modal isOpen={createModalOpen} onClose={() => setCreateModalOpen(false)} title="Add New Employee directly to ERPNext">
        <form onSubmit={handleCreateSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">First Name</label>
              <input
                type="text"
                required
                value={formData.first_name}
                onChange={e => setFormData({ ...formData, first_name: e.target.value })}
                placeholder="First Name"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Last Name</label>
              <input
                type="text"
                value={formData.last_name}
                onChange={e => setFormData({ ...formData, last_name: e.target.value })}
                placeholder="Last Name"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Gender</label>
              <select
                value={formData.gender}
                onChange={e => setFormData({ ...formData, gender: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
              >
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Other">Other</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Date of Birth</label>
              <input
                type="date"
                required
                value={formData.date_of_birth}
                onChange={e => setFormData({ ...formData, date_of_birth: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Company</label>
              <input
                type="text"
                readOnly
                value={formData.company}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 bg-slate-50 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Date of Joining</label>
              <input
                type="date"
                required
                value={formData.date_of_joining}
                onChange={e => setFormData({ ...formData, date_of_joining: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Designation</label>
              <input
                type="text"
                required
                value={formData.designation}
                onChange={e => setFormData({ ...formData, designation: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Department</label>
              <select
                value={formData.department}
                onChange={e => setFormData({ ...formData, department: e.target.value })}
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
              >
                {departments.map(d => (
                  <option key={d.name} value={d.name}>{d.department_name || d.name}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Personal Email</label>
              <input
                type="email"
                value={formData.personal_email}
                onChange={e => setFormData({ ...formData, personal_email: e.target.value })}
                placeholder="personal@example.com"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1">Company Email</label>
              <input
                type="email"
                value={formData.company_email}
                onChange={e => setFormData({ ...formData, company_email: e.target.value })}
                placeholder="official@faircode.com"
                className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
              />
            </div>
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setCreateModalOpen(false)}
              className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
            >
              Create Employee in ERPNext
            </button>
          </div>
        </form>
      </Modal>

      {/* Edit Employee Modal */}
      <Modal isOpen={editModalOpen} onClose={() => setEditModalOpen(false)} title={`Edit Employee: ${editFormData?.name}`}>
        {editFormData && (
          <form onSubmit={handleEditSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">First Name</label>
                <input
                  type="text"
                  required
                  value={editFormData.first_name || ''}
                  onChange={e => setEditFormData({ ...editFormData, first_name: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Last Name</label>
                <input
                  type="text"
                  value={editFormData.last_name || ''}
                  onChange={e => setEditFormData({ ...editFormData, last_name: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Designation</label>
                <input
                  type="text"
                  required
                  value={editFormData.designation || ''}
                  onChange={e => setEditFormData({ ...editFormData, designation: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Department</label>
                <select
                  value={editFormData.department || ''}
                  onChange={e => setEditFormData({ ...editFormData, department: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
                >
                  {departments.map(d => (
                    <option key={d.name} value={d.name}>{d.department_name || d.name}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Status</label>
                <select
                  value={editFormData.status || 'Active'}
                  onChange={e => setEditFormData({ ...editFormData, status: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white font-semibold"
                >
                  <option value="Active">Active</option>
                  <option value="Left">Left</option>
                  <option value="Suspended">Suspended</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Employment Type</label>
                <select
                  value={editFormData.employment_type || 'Full-time'}
                  onChange={e => setEditFormData({ ...editFormData, employment_type: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none bg-white"
                >
                  <option value="Full-time">Full-time</option>
                  <option value="Part-time">Part-time</option>
                  <option value="Contract">Contract</option>
                  <option value="Intern">Intern</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Personal Email</label>
                <input
                  type="email"
                  value={editFormData.personal_email || ''}
                  onChange={e => setEditFormData({ ...editFormData, personal_email: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Company Email</label>
                <input
                  type="email"
                  value={editFormData.company_email || ''}
                  onChange={e => setEditFormData({ ...editFormData, company_email: e.target.value })}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 outline-none"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
              <button
                type="button"
                onClick={() => setEditModalOpen(false)}
                className="px-4 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-sm"
              >
                Save Changes to ERPNext
              </button>
            </div>
          </form>
        )}
      </Modal>
    </div>
  )
}
