/**
 * Centralized ERPNext API Client
 * Manages baseURL, session headers, CSRF, error formatting
 */

const BASE_URL = import.meta.env.VITE_ERPNEXT_URL || ''

function getCookie(name) {
	const value = `; ${document.cookie}`
	const parts = value.split(`; ${name}=`)
	if (parts.length === 2) return parts.pop().split(';').shift()
	return null
}

function getCsrfToken() {
	if (typeof window !== 'undefined') {
		if (window.csrf_token && window.csrf_token !== 'None' && window.csrf_token !== '{{ csrf_token }}') {
			return window.csrf_token
		}
		if (window.frappe?.csrf_token && window.frappe.csrf_token !== 'None') {
			return window.frappe.csrf_token
		}
		if (window.frappe?.boot?.csrf_token) {
			return window.frappe.boot.csrf_token
		}
	}
	return getCookie('csrf_token')
}

export function formatErrorMessage(error) {
	if (!error) return 'An unexpected error occurred'
	if (typeof error === 'string') return error

	if (error.response) {
		const status = error.status || error.response.status
		const data = error.response.data || {}

		// Handle AuthenticationError (401 or exc_type/exception)
		if (
			status === 401 ||
			data.exc_type === 'AuthenticationError' ||
			(typeof data.exception === 'string' && data.exception.includes('AuthenticationError'))
		) {
			return typeof data.message === 'string' && data.message && !data.message.includes('frappe.exceptions')
				? data.message
				: 'Invalid username or password. Please check your credentials.'
		}

		// Try parsing Frappe exception messages
		if (data._server_messages) {
			try {
				const messages = JSON.parse(data._server_messages)
				const parsed = messages.map(m => {
					try {
						const obj = JSON.parse(m)
						return obj.message || obj
					} catch {
						return m
					}
				})
				const joined = parsed.join('; ').trim()
				if (joined) return joined
			} catch (e) {
				// ignore parse error
			}
		}

		// If clean data.message is present, prefer it
		if (data.message) {
			if (typeof data.message === 'string' && !data.message.startsWith('frappe.exceptions.')) {
				return data.message
			}
			if (typeof data.message === 'object' && data.message.message) {
				return data.message.message
			}
		}

		if (data.exception && typeof data.exception === 'string') {
			// Extract human readable part of exception if colon present
			const parts = data.exception.split(':')
			if (parts.length > 1) {
				return parts.slice(1).join(':').trim()
			}
			// If it's a raw python class name without colon, provide human readable equivalent
			if (data.exception.startsWith('frappe.exceptions.')) {
				const excName = data.exception.replace('frappe.exceptions.', '')
				if (excName === 'AuthenticationError') {
					return 'Invalid username or password. Please check your credentials.'
				}
				if (excName === 'PermissionError') {
					return 'You do not have permission to perform this action.'
				}
				if (excName === 'DoesNotExistError') {
					return 'The requested record was not found on ERPNext.'
				}
				return excName
			}
			return data.exception
		}

		switch (status) {
			case 401:
				return 'Invalid username or password. Please check your credentials.'
			case 403:
				return 'You do not have permission to perform this action.'
			case 404:
				return 'The requested resource was not found on ERPNext.'
			case 409:
				return 'Conflict: Record already exists or version mismatch.'
			case 500:
				return 'ERPNext Server Error. Please verify server logs or document state.'
			default:
				return `Server error (${status}): ${data.exc_type || 'Unknown error'}`
		}
	}

	if (error.message) {
		if (error.message.includes('Failed to fetch') || error.message.includes('NetworkError')) {
			return 'Unable to connect to ERPNext. Please check your network and server status.'
		}
		return error.message
	}

	return 'An unexpected error occurred while communicating with ERPNext.'
}

async function request(endpoint, options = {}) {
	const url = endpoint.startsWith('http') ? endpoint : `${BASE_URL}${endpoint}`

	const headers = {
		'Accept': 'application/json',
		'X-Frappe-CSRF-Token': getCsrfToken() || '',
		...(options.headers || {}),
	}

	if (!(options.body instanceof FormData)) {
		headers['Content-Type'] = headers['Content-Type'] || 'application/json'
	}

	const config = {
		credentials: 'include',
		headers,
		...options,
	}

	try {
		const response = await fetch(url, config)

		let data
		const contentType = response.headers.get('content-type')
		if (contentType && contentType.includes('application/json')) {
			data = await response.json()
		} else {
			data = await response.text()
		}

		if (!response.ok) {
			const error = new Error(`Request failed with status ${response.status}`)
			error.status = response.status
			error.response = { status: response.status, data }
			error.userMessage = formatErrorMessage(error)
			throw error
		}

		return data
	} catch (err) {
		if (!err.userMessage) {
			err.userMessage = formatErrorMessage(err)
		}
		throw err
	}
}

export const api = {
	get: (endpoint, params) => {
		let url = endpoint
		if (params) {
			const query = new URLSearchParams()
			for (const [key, val] of Object.entries(params)) {
				if (val !== undefined && val !== null) {
					query.append(key, typeof val === 'object' ? JSON.stringify(val) : val)
				}
			}
			const qs = query.toString()
			if (qs) url += (url.includes('?') ? '&' : '?') + qs
		}
		return request(url, { method: 'GET' })
	},

	post: (endpoint, body) => {
		const isFormData = body instanceof FormData
		return request(endpoint, {
			method: 'POST',
			body: isFormData ? body : JSON.stringify(body || {}),
		})
	},

	put: (endpoint, body) => {
		return request(endpoint, {
			method: 'PUT',
			body: JSON.stringify(body || {}),
		})
	},

	delete: (endpoint) => {
		return request(endpoint, { method: 'DELETE' })
	},
}

export default api

