import api from './client'

export const candidateService = {
  async registerCandidate({ firstName, lastName, username, fullName, email, password, confirmPassword, phone }) {
    const res = await api.post('/api/method/hrms.api.candidate_api.register_candidate_user', {
      first_name: firstName,
      last_name: lastName,
      username,
      full_name: fullName,
      email,
      password,
      confirm_password: confirmPassword,
      phone,
    })
    return res.message || res.data
  },

  async getActiveJobOpenings() {
    const res = await api.get('/api/method/hrms.api.candidate_api.get_active_job_openings')
    return res.message || res.data || []
  },

  async submitApplication(applicationData) {
    const res = await api.post('/api/method/hrms.api.candidate_api.submit_candidate_application', {
      data: applicationData,
    })
    return res.message || res.data
  },

  async getMyApplications() {
    const res = await api.get('/api/method/hrms.api.candidate_api.get_candidate_applications')
    return res.message || res.data || []
  },

  async getApplicationDetail(name) {
    const res = await api.get('/api/method/hrms.api.candidate_api.get_candidate_application_detail', {
      name,
    })
    return res.message || res.data
  },

  async markNotificationRead(name, notificationIdx) {
    const res = await api.post('/api/method/hrms.api.candidate_api.candidate_mark_notification_read', {
      name,
      notification_idx: notificationIdx,
    })
    return res.message || res.data
  },

  async updateProfile(profileData) {
    const res = await api.post('/api/method/hrms.api.candidate_api.update_candidate_profile', {
      data: profileData,
    })
    return res.message || res.data
  },

  // Admin Actions
  async getCandidatesList() {
    const res = await api.get('/api/method/hrms.api.candidate_api.get_candidates_list')
    return res.message || res.data || []
  },

  async adminGetApplications(filters = {}) {
    const res = await api.get('/api/method/hrms.api.candidate_api.admin_get_candidate_applications', {
      filters: JSON.stringify(filters),
    })
    return res.message || res.data || []
  },

  async adminUpdateStatus(name, status, hrRemarks = '') {
    const res = await api.post('/api/method/hrms.api.candidate_api.admin_update_application_status', {
      name,
      status,
      hr_remarks: hrRemarks,
    })
    return res.message || res.data
  },

  async adminScheduleInterview({ name, stage = 'Interview 1', scheduled_on, interviewer, call_url = 'https://meet.google.com/home', remarks = '' }) {
    const res = await api.post('/api/method/hrms.api.candidate_api.admin_schedule_interview', {
      name,
      stage,
      scheduled_on,
      interviewer,
      call_url,
      remarks,
    })
    return res.message || res.data
  },

  async adminMarkInterviewCompleted({ name, stage = 'Interview 1', remarks = '' }) {
    const res = await api.post('/api/method/hrms.api.candidate_api.admin_mark_interview_completed', {
      name,
      stage,
      remarks,
    })
    return res.message || res.data
  },

  async adminRecordInterviewResult({ name, stage = 'Interview 1', result = 'Selected', remarks = '' }) {
    const res = await api.post('/api/method/hrms.api.candidate_api.admin_record_interview_result', {
      name,
      stage,
      result,
      remarks,
    })
    return res.message || res.data
  },

  async uploadResume(file) {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('is_private', '0')
    const res = await api.post('/api/method/upload_file', formData)
    return res.message?.file_url || res.data?.file_url
  },

  async selectCandidateAsEmployee(applicationName, candidateId = null) {
    const res = await api.post('/api/method/hrms.api.candidate_api.select_candidate_as_employee', {
      application_name: applicationName,
      candidate_id: candidateId,
    })
    return res.message || res.data
  },
}

export default candidateService

